programs.sol:
"""Detect `void` and uncommon -oid/-oyd endings, not a general code feature.

Return-type void is strong; test annotations, parameters, and the noun 'the void'
are weaker. Productive -oid endings are recognized across token boundaries,
with short plural/adjective continuations. Common lexicalized words are exempt.
Related split oyd, French oïd, and Cyrillic ойд/ойти spellings are positive;
split French oix/oie endings are negative. Iod fragments and the :: after
a void-qualified class name also get positive values. Other tokens predict zero.
Only a short trailing context is kept, reset at document boundaries.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, previous, last_doc = carry or ('', '', doc)
    if doc != last_doc:
        history, previous = '', ''
    token = prefix.token_strings[-1]
    lower = token.lower()
    joined = history + lower
    line = history.rsplit('\n', 1)[-1]
    plain = ''.join(c for c in unicodedata.normalize('NFD', joined[-48:])
                    if not unicodedata.combining(c))
    match = re.search(r'[a-z]+$', plain)
    word = match[0] if match else ''
    value = 0.0
    if lower.strip() == 'void':
        value = 6.8
        if token.strip() == 'Void':
            value = 5.0
        if '\t' in joined.rsplit('\n', 1)[-1]:
            value += 1.0
        if re.search(r'(?:@test|\[test)[^{};]*$', history):
            value = 3.2
        elif re.search(r'[-+]\s*\($', line):
            value = 6.8
        elif line.rstrip().endswith(('(', ',', '=>', ':')):
            value = 2.8
        elif re.search(r'\bthe\s*$', history):
            value = 3.4
    elif lower.lstrip().startswith(('(void', '<void', ',void')):
        value = 1.8
    elif any(x in word for x in ('avoid', 'devoid', 'android', 'embroid')):
        pass
    elif word == 'poids':
        pass
    elif 'oid' in lower:
        bound = lower.isalpha() and len(word) > len(lower)
        value = (10.0 if lower == 'oid' else 8.0) if bound else 6.0
        if word in ('oid', 'oids'):
            value = 3.0
        if word.endswith('trapezoid'):
            value = 2.4
        elif word.endswith(('thyroid', 'asteroid', 'steroids', 'opioids')):
            value = 4.7
        elif 'sinusoid' in word:
            value = 4.8
        elif word.endswith(('froid', 'froids')):
            value = 1.2
    elif 'oyd' in lower:
        value = 7.0 if lower.isalpha() and len(word) > len(lower) else 3.0
    elif re.fullmatch(r'd(?:s|e|es)?|id(?:s|e|es|y|al|eos)', lower) and re.search(
        r'oid|oyd', previous[-2:] + lower
    ):
        value = 8.0
    elif lower == 'ed' and previous.endswith('loy'):
        value = 4.5
    elif lower == 'ï' and previous.endswith('o'):
        value = 8.0
    elif lower == 'de' and previous.endswith('ï'):
        value = 8.0
    elif lower in ('s', 'es', 'al', 'ally', 'ed') and previous.endswith('oid'):
        value = {'s': 4.5, 'es': 7.5, 'al': 6.5, 'ally': 3.0, 'ed': 1.5}[lower]
    elif lower in ('ix', 'ie') and previous.endswith('o'):
        value = -4.0 if lower == 'ix' else -2.5
    elif lower == 'д' and previous.endswith(('ой', 'ый')):
        value = 4.5
    elif lower == 'ти' and previous.endswith('ой'):
        value = 2.5
    elif lower == 'iod' and token != 'IOD':
        value = 3.0
    elif lower == '::' and re.search(r'\bvoid\s+\w+$', history):
        value = 3.0
    return ((history + lower)[-160:], lower, doc), value

"""Approximate a lexical response centered on Chinese/Japanese 取 (take).

A separate 取 token is strongly negative, especially at document start.
Reading/extraction compounds, Japanese text and code/number contexts weaken
it. Larger tokens containing 取 usually have smaller negative responses.
The qu relatives 趣, 娶 and split-byte 趨, and selected Asian spellings
of taking/seeking, are also negative. This is not a universal semantic
"take" detector: it depends on the actual spelling and token boundaries.

Smaller independent rules cover negative 鹿 (deer), positive Chinese legal
vocabulary (stronger in some political/legal collocations), repeated middle
dots, and an opening decimal prefix 12. Unlisted tokens return zero.
Document-local history is reset at every document boundary. These rules
leave most small lexical variation unexplained.
"""
import re

READS = ()
KANA = re.compile(r'[\u3040-\u30ff]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, count = '', 0
        recent_bytes = b''
    else:
        _, history, count, recent_bytes = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    if word == '取':
        if count == 0:
            value = -9.2
        elif history.endswith(('读', '讀', '読')):
            value = -1.5
        elif history.endswith(('摘', '攫', '截', '窃', '竊', '抓', '摂', '切り')):
            value = -2.7
        elif history.endswith(('谋', '謀', '争', '爭', '奪', '榨')):
            value = -4.9
        # Numeric values and code-mixed uses have a weaker response.
        elif history.endswith('值'):
            value = -3.1
        elif history.endswith(('数', '數', '差')):
            value = -4.6
        elif KANA.search(history):
            value = -5.2
        elif re.search(r'[A-Za-z]{2,}', history[-12:]):
            value = -4.8
        else:
            value = -6.8
    elif '取' in word:
        if word == 'を取り':
            value = -4.15
        elif word == '取り' or word.startswith('取得'):
            value = -2.6
        elif word.startswith('取消'):
            value = -2.7
        elif word.startswith(('取代', '取决')):
            value = 0.0
        elif word in ('采取', '採取', '争取', '爭取', '领取', '領取', '取暖'):
            value = -0.8
        elif word == '进取':
            value = -4.2
        else:
            value = -1.8
        if token.startswith(' '):
            value *= 0.3
    elif word in ('趣', '趣味', '娶'):
        value = -1.8
    elif '趣' in word:
        value = -0.4
    elif word in ('취', 'lấy'):
        value = -3.0
    elif word == 'เอา':
        value = -1.1
    elif word == '鹿':
        value = -2.8
    elif word == '法治':
        value = 4.4
    elif word in ('纪律', '紀律'):
        value = 2.8 if history.endswith('政治') else 1.1
    elif word == '法律':
        value = 1.1
    elif word in ('法规', '法規'):
        value = 5.2 if history.endswith(('党内', '黨內')) else 1.1
    elif word == '法律法规':
        value = 2.9
    elif word in ('制度', '宪法', '憲法', '规矩', '規矩'):
        value = 2.1 if word == '制度' and history.endswith('法律') else 0.4
    elif word == '··' and (count == 0 or history.endswith('·')):
        value = 1.84
    elif word == '2':
        if count == 1 and history == '1':
            value = 2.98
        elif count == 2 and history == '12':
            value = 1.35
    elif word == '구' and history.endswith(('추', '탐', '강')):
        # The final syllable of Korean words for pursue/explore/seek.
        value = -2.5 if history.endswith('추') else -0.9

    recent_bytes = (recent_bytes + prefix.token_bytes[-1])[-6:]
    if '\ufffd' in token and recent_bytes.endswith('趨'.encode('utf-8')):
        # This traditional character is often split across UTF-8 tokens.
        value = -2.0
    return (doc, (history + token)[-40:], count + 1, recent_bytes), value

"""Sparse surface cues at document openings and in quantified expressions.

Large positives mark an initial Title: header, the first 2 after opening 1s,
and an opening run of carriage returns. Weaker rules mark line-leading 1,
identifier suffix 5, split five-words and indefinite compounds. English and
Chinese singular-choice phrases tend negative; a Thai consonant cluster gets
its own positive correction. Ordinary text stays near zero.

This approximates the conspicuous responses, not the many small fluctuations.
State tracks the document boundary, current line and unfinished ASCII word.
"""
import re
import inflect

READS = ()
CHOICE_WORDS = {'each', 'any', 'which', 'whichever'}
VERSION_STEMS = {'md', 'html', 'hdf', 'php', 'sha'}
COMPOUNDS = tuple(
    a + b for a in ('some', 'any', 'every', 'no')
    for b in ('one', 'thing', 'body', 'where')
) + ('elsewhere',)
# Spellings, plurals and ordinals come from English inflection rules.
_english = inflect.engine()
FIVE_WORDS = tuple(
    _english.number_to_words(form)
    for n in (5, 15, 50)
    for form in (n, _english.ordinal(n))
)
FIVE_PLURAL = _english.plural(FIVE_WORDS[0])
FIVE_WORDS += (FIVE_PLURAL, _english.plural(FIVE_WORDS[1]))
ONE_SELECTORS = {'这', '這', '那', '某', '又', '上', '下', '前', '后',
                 '另', '另外', '其中', '最后', '最後', '这样'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, before, initial = 0, '', '', token
        same, empty_line, running = True, True, ''
    else:
        _, position, previous, before, initial, same, empty_line, running = carry
        position += 1

    value = -0.16 if position == 0 else 0.0
    word = token.strip().lower()
    prev_word = previous.strip().lower()
    # A current token may finish a word begun in an earlier token.
    leading = re.match(r'[A-Za-z]+', token)
    joined = running + leading.group().lower() if leading else ''
    compound = (len(running) >= 2 and len(joined) >= 5 and
                any(w.startswith(joined) for w in COMPOUNDS))
    five_piece = (bool(running) and len(joined) >= 3 and
                  any(w.startswith(joined) for w in FIVE_WORDS))
    if token == '\r':
        value = 2.08 if initial == '\r' and same else -0.10
    elif position == 0:
        if token == 'Title':
            value = -1.34
        elif token == '`':
            value = 1.86
        elif token == '<|endoftext|>':
            value = -2.97
        elif token == '//\n':
            value = 1.65
        elif token == '1':
            value = 0.24
        elif word.isascii() and word.isalpha():
            if len(word) >= 4:
                unspaced_or_title = (
                    not token.startswith(' ') or token.strip().istitle()
                )
                value = -0.4 if unspaced_or_title else -0.2
            elif len(word) == 1:
                value = 0.12
        elif token.isdigit():
            value = 0.1
    elif position == 1 and previous == 'Title' and token == ':':
        value = 6.25
    elif token == '2' and initial == '1' and same:
        value = max(0.0, 5.04 - 0.51 * (position - 1))
    elif token == '1':
        if '\n' in previous or empty_line:
            value = 0.30 + 0.12 * (previous.count('\n') > 1)
            if ':' in previous:
                value = 0.56
            if '：' in previous:
                value = 0.98
        elif previous in {'1', '2'}:
            value = 0.10
    elif token == '5':
        value = 0.055
        if prev_word.lstrip('/.') in VERSION_STEMS:
            value = 1.30
        elif prev_word.isascii() and prev_word.isalpha():
            value = 0.30
        elif previous == '6':
            value = 0.24
        elif previous in {'2', '5'}:
            value = -0.05
        elif previous == '.':
            value = -0.10
        elif previous.isspace():
            value = 0.12
    elif five_piece:
        value = 2.0 if joined == FIVE_PLURAL else 0.75
    elif compound:
        value = 0.65
    elif word in {'thing', 'where'} and prev_word in {'some', 'any', 'every', 'else'}:
        value = 0.65
    elif word == 'one' and prev_word == 'some':
        value = 0.65
    elif word == 'one' and prev_word in CHOICE_WORDS:
        value = -0.50
    elif word == 'of' and prev_word == 'one':
        selected = before.strip().lower() in CHOICE_WORDS | {'every'}
        value = -1.3 if selected else -0.04
    elif token.startswith('一') and previous in {'每', '任', '哪', '另'}:
        value = -1.3
    elif token.startswith('一') and previous in ONE_SELECTORS:
        value = -0.65
    elif token.startswith(('每一', '某一')):
        value = -0.65
    elif token in {'这一', '那一', '同一', '另一'}:
        value = -0.6
    # Thai consonant cluster, used in words such as 'front' and 'one'.
    elif token == 'หน':
        value = 1.15

    if '\n' in token:
        empty_line = not token.rsplit('\n', 1)[-1].strip()
    else:
        empty_line = empty_line and not token.strip()
    same = same and token == initial
    tail = re.search(r'[A-Za-z]+$', token)
    if tail:
        whole_piece = leading and leading.end() == len(token)
        running = joined if whole_piece else tail.group().lower()
        running = running[-24:]
    else:
        running = ''
    return (doc, position, token, previous, initial, same, empty_line, running), value

"""Detect blank lines that close a multiline block, rather than plain prose.

The state counts tokens since the last blank line and the last line break,
plus intervening line breaks. A blank line is stronger when earlier lines
occupy a noticeable part of its block, especially after several lines.
Merged punctuation and whitespace distinguish weaker boundary types.
Document starts reset the counts and receive a separate negative baseline.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        paragraph = line = breaks = previous_punctuation = 0
    else:
        _, paragraph, line, breaks, previous_punctuation = carry

    text = prefix.token_strings[-1].replace('\r\n', '\n')
    newlines = text.count('\n')
    blank = '\n\n' in text
    value = 0.0
    if blank:
        body = text.split('\n', 1)[0]
        # At least about a sixth of the block precedes its final line.
        multiline = paragraph + 1 > 1.18 * (line + 1)
        if not body:
            if multiline:
                value = 1.72 if breaks <= 2 else 2.28
                if previous_punctuation >= 2:
                    value += 0.25
            else:
                value = 1.70 if previous_punctuation >= 3 else 0.42
        elif multiline:
            value = 1.12 if breaks <= 3 else 1.49
        elif body == ' ':
            value = -0.14
        elif ',' in body:
            value = -0.17
        else:
            value = 0.42 if ' ' in body else 0.18
        if newlines >= 3:
            value = max(value, 1.50 if not body else 1.20)

    if first:
        special = text.startswith('<|') and text.endswith('|>')
        value = 0.0 if special else -0.55
        if blank:
            value = -1.32 if not body else -2.45 if body == ' ' else -0.78

    # Repeated middle dots are another typographic separator.
    if len(text) >= 2 and not text.strip('·'):
        value = 3.52

    paragraph += 1
    line += 1
    if newlines:
        line = 0
        breaks += newlines
    if blank:
        paragraph = breaks = 0
    punctuation = min(3, sum(not c.isalnum() and not c.isspace() for c in text))
    return (doc, paragraph, line, breaks, punctuation), value

programs.haiku:
"""Paragraph-break detector: layer 1's MLP output, component 2371.

What it does. The component responds to the token that ends a paragraph or block,
one whose text contains a blank line ("\n\n", ")\n\n", ".\n\n", "\r\n\r\n", ...).
How large it is depends on what the break follows:

- a break after a closing bracket, quote, backtick or markup tag is large (1.0);
- a bare break ("\n\n" alone) right after such a closer, e.g. "</think>\n\n", is
  larger still (2.0);
- a break after a sentence-ending period, question or exclamation mark is small (0.27);
- a break after a comma or a bare space is slightly negative (-0.13);
- a token with three or more newlines is large (1.2);
- a bare break is large (1.0) when no break came in the last 30 tokens of its
  document, and modest (0.4) when it closes a paragraph that is short.

The first token of each document, which the model reads with no context, is
negative (-0.6). Every other token predicts 0.

Inputs: the newest token, the token before it, the position and document labels,
and the position of the last break in the document (the carry).
"""

READS = ()

DOC_START = -0.6
LONG_RUN = 30
CLOSERS = set(")]};>\"'`|")
SENTENCE_END = set(".?!")


def is_break(tok):
    return "\n\n" in tok or "\r\n\r\n" in tok


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[-1]
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        carry = None  # no break yet in this document
    value = 0.0
    if new_doc:
        value = DOC_START
    elif is_break(tok):
        last = tok.rstrip("\r\n")[-1:]
        prev = prefix.token_strings[-2].strip()
        if tok in (" \n\n", ",\n\n"):
            value = -0.13
        elif "\n\n\n" in tok:
            value = 1.2
        elif last in SENTENCE_END:
            value = 0.27
        elif last in CLOSERS:
            value = 1.0
        elif len(prev) > 1 and prev[-1:] in CLOSERS:
            value = 2.0
        else:
            gap = LONG_RUN if carry is None else t - carry
            value = 1.0 if gap >= LONG_RUN else 0.4
    if is_break(tok):
        carry = t
    return carry, value

programs.sol:
"""A lexical detector for democracy, forms of rule, and related Greek stems.

Negative responses peak on democracy and its translations, especially where a
split token completes the root. Monarchy, hierarchy and -crat/-cracy words are
weaker relatives. Quadratic and a few scientific stems are spelling side
responses. Community/public compounds give a smaller positive response.
Only a short text tail is retained; document boundaries clear it.
"""
import re
import regex
from anyascii import anyascii

READS = ()
_WORD = re.compile(r"[^\W\d_]+\Z")


def word_end(text):
    match = _WORD.search(text)
    return match.group() if match else ''


def value(previous, text, token):
    raw = word_end(text)
    if not token or not raw:
        return 0.0
    word = anyascii(raw).lower()
    t = anyascii(token.strip()).lower()
    context = previous.lower().rstrip()
    # Equivalent terms for democracy and other forms of rule.
    translations = (
        ('民主', -10.9), ('民主党', -5.2), ('민주', -13.0),
        ('dân chủ', -10.4), ('君主', -6.1), ('官僚', -10.7),
    )
    for ending, score in translations:
        if text.endswith(ending):
            return score
    if '民主' in token:
        return -5.2
    if 'democr' in word or 'demokr' in word:
        if t == 'democratic':
            return -7.3 if token.strip()[0].isupper() else -8.8
        if t == 'democracy':
            return -8.3
        if t == 'democrat':
            return -6.0 if context.endswith('liberal') else (
                -2.9 if token.strip()[0].isupper() else -6.4)
        if t == 'democrats':
            return -1.7
        if t in ('s', 'es', 'er', 'en', 'chen', 'cher', 'ke', 'us'):
            return 0.0  # An extra inflection is not a new root.
        if t == 'democr':
            return -7.2
        if 'demok' in word:
            if regex.search(r'\p{Script=Cyrillic}', raw):
                return -14.0 if t in ('rat', 'r') else -4.3
            if t == 'rat':
                return -17.8
            if t in ('r', 'atis', 'atische', 'ie'):
                return -11.2
            return -3.6
        if t == 'ocr':
            return -13.9
        if t in ('ocrat', 'ocratic'):
            return -10.7
        if t == 'atie':
            return -12.5
        return -6.7 if t == 'acies' else -4.8
    if word.endswith('demok'):
        return -0.2 if regex.search(r'\p{Script=Cyrillic}', raw) else -5.5
    # Related stems: stop responding once a longer word moves past them.
    if 'quadrat' in word:
        if t == 'quadratic' or t == 'adratic':
            return -3.7
        if t in ('atic', 'atically'):
            return -5.8
        return -3.8 if t == 'atics' else (-1.9 if t == 'at' else 0.0)
    if 'hierarch' in word:
        if t == 'hierarchy':
            return -1.7
        if t in ('arch', 'archical', 'hierarchical', 'ierarchical'):
            return -3.5
        return -2.5 if t == 'ies' else 0.0
    if 'monarch' in word or 'monarqu' in word:
        if t in ('monarch', 'monarchy', 'archy', 'ist'):
            return -2.1
        if t in ('qu', 'quia', 'ia', 'ie', 'archical'):
            return -8.0 if t in ('qu', 'archical') else -6.5
        return -0.6 if t == 's' else 0.0
    if 'bureaucr' in word or 'burokr' in word:
        return -9.0 if t in ('kr', 'atische') else -4.8
    if 'ocrat' in word or 'ocrac' in word or 'crat' in word[1:]:
        if t in ('ocrat', 'ocratic', 'atic', 'rat'):
            return -8.3
        if t in ('ocracy', 'a', 'ate'):
            return -5.8
        if t == 'ocrates':
            return -1.7
        return -2.5 if t in ('ocrats', 'crate', 'rate') else 0.0
    if 'craz' in word and word.startswith(('auto', 'demo', 'aristo')):
        return -9.0 if t in ('raz', 'ia') else 0.0
    if 'mediocr' in word:
        return -11.0 if t == 'ocr' else (-4.8 if t == 'ity' else 0.0)
    if 'hypocrit' in word and t == 'ritical':
        return -5.5
    if t == 'ocr':
        return -3.5
    # Recognizable biological word parts, not every occurrence of "cy".
    if t == 'otic' and 'karyot' in word:
        return -4.6
    if t == 'cy' and word.endswith(('dendrocy', 'erythrocy', 'chondrocy')):
        return -1.9
    if t == 'ocrine':
        return -2.7
    if t == 'last' and word.endswith('oclast'):
        return -4.0
    # Social compounds have a smaller, context-dependent response.
    if t == '-based' and context.endswith(('home', 'community', 'population')):
        return 4.3
    if t == '-changing' and context.endswith('life'):
        return 1.1
    if t in ('class', 'classes', '-class') and context.endswith('middle'):
        return -4.2
    if t in ('group', 'groups') and context.endswith(('community', 'society', 'family')):
        return 4.5
    if context.endswith('public'):
        if t == 'health':
            return 1.1
        if t in ('security', 'broadcasting'):
            return 4.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    newest = prefix.token_bytes[-1]
    tail = (old + newest)[-256:]
    score = value(old.decode('utf-8', 'ignore'),
                  tail.decode('utf-8', 'ignore'),
                  newest.decode('utf-8', 'ignore'))
    return (doc, tail), score

"""A partial, mixed feature: negative on short uy/uim and related vowel
spellings; positive on Chinese doing/achieving and procedure vocabulary.
CC-CEDICT distinguishes these meanings from finishing or understanding.
Recent Latin letters damp positive Chinese matches; recent kana suppress them.
Periodicity words have a separate negative response.
There are also document-opening Title:, def, #include, and PHP-tag signals.
Unmatched tokens get zero; document boundaries reset the small context state.
"""
from functools import lru_cache
import re
import regex
import cedict
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def chinese_value(text):
    if not regex.fullmatch(r'\p{Script=Han}{2,6}', text):
        return 0.0
    # Remove modal prefixes and aspect suffixes, e.g. "must do" / "has done".
    root = text.lstrip('要能应需').rstrip('了着过中')
    if not root:
        return 0.0
    gloss = '; '.join(cedict.glosses(root)).lower()
    if 'to accomplish' in gloss and 'to achieve' in gloss:
        return 4.5
