            value -= 1.2
        elif low.startswith('pe'):
            value -= 2.8
        else:
            value -= 3.1
    if low in ('.p', '-p') and old.endswith('i'):
        value -= 3.0
    if joined:
        value += echo
    if s and s[0].isdigit() and old.rstrip().endswith('i'):
        value += 0.77 + (1.14 if s[0] in '6789' else 0.0)
    if old.strip() == 'intellectual' and low.strip() == 'property':
        value -= 3.65 + (2.0 if prev.istitle() and s.istitle() else 0.0)
    if old.strip() == 'internet' and low.strip() == 'protocol':
        value -= 3.0
    if 'ip' not in low[-4:]:
        next_echo = 0.0
    else:
        next_echo += 0.5 * reinforcement
    value += 0.11 if start else 0.0
    return (doc, s, low, next_echo), value

"""A conditional/concessive marker detector, mostly inactive elsewhere.

Ordinary prose 'if' is negative; 'even if' is much stronger. Embedded
questions ('check if', 'know if') and indented code are mostly suppressed.
Word frequencies in recent text disambiguate Romance-language si/se.
Russian, Ukrainian, Vietnamese, and Chinese condition markers are included.
Chinese restrictive/time adverbs are negative; personal/individual is positive.
Byte tails allow a Chinese marker to span tokenizer boundaries.
Two formatting responses are also modeled: a document-initial 'Title:'
colon is strongly positive, and repeated middle dots are negative.
"""
import re
from wordfreq import zipf_frequency

READS = ()
# Verbs introducing an embedded question rather than a condition.
QUESTION_VERBS = {
    'ask', 'check', 'determine', 'discover', 'find', 'know', 'see',
    'tell', 'test', 'verify', 'wonder', 'decide', 'sure',
}
CHINESE = {
    # If / assuming; even if; although / regardless.
    '如果': -0.61, '假如': -0.6, '假若': -0.6, '倘若': -0.6,
    '若': -0.35, '若是': -0.42,
    '即使': -10.8, '即便': -8.7, '就算': -7.3,
    '哪怕': -9.4, '哪怕是': -7.0,
    '虽然': -0.8, '雖然': -0.8, '尽管': -2.2, '儘管': -2.2,
    '不管': -1.24, '无论': -0.7, '無論': -0.7,
    # Exceptions, restrictive focus, and temporal adverbs.
    '除非': -1.4, '直到': -2.0, '明明': -2.4,
    '只需': -1.8, '隻需': -4.0, '只需要': -1.2, '只管': -3.6,
    '即刻': -4.0, '即日': -2.8, '即時': -6.8,
    '及时': -1.4, '及時': -2.8, '顺便': -2.0, '順便': -2.0,
    '不断': -1.0, '不斷': -1.6, '不断地': -1.5, '不斷地': -1.5,
    '特地': -2.0,
    # A separate, positive response to personal/individual.
    '个人': 2.65, '個人': 2.4,
}


def language(context):
    """Identify the likely language from the last twenty words' frequencies."""
    words = re.findall(r'[^\W\d_]{2,}', context.lower())[-20:]
    if not words:
        return ''
    return max(('fr', 'es', 'it', 'pt', 'en'), key=lambda lang:
               sum(zipf_frequency(w, lang) for w in words))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, count, tail = '', 0, b''
    else:
        _, previous, count, tail = carry
    old_text = tail.decode('utf-8', 'ignore')
    newest = prefix.token_bytes[-1]
    tail = (tail + newest)[-512:]
    text = tail.decode('utf-8', 'ignore')
    raw = prefix.token_strings[-1]
    token = raw.strip()
    prev = previous.strip()
    word = token.lower()
    before = prev.lower()
    value = 0.0

    if token == ':' and previous == 'Title' and count == 1:
        value = 21.05
    elif token and not token.strip('·') and len(token) >= 2:
        value = -1.57
    elif before == 'even':
        initial = prev[:1].isupper()
        if word == 'if':
            value = -6.15 if initial else -4.82
            if token.isupper() or token == 'If':
                value = -3.2
        elif word == 'though':
            value = -0.85 if initial else -0.53
        elif word in {'when', 'after', 'before', 'until', 'with', 'without'}:
            value = -2.8 if initial else -1.7
        elif word in {'in', 'at', 'for'}:
            value = -1.5 if initial else -0.7
    elif word == 'if':
        if token == 'If':
            value = -0.76 if raw.startswith(' ') else -0.62
        elif token == 'IF':
            value = -0.12 if raw.startswith(' ') else 0.2
        elif raw == ' if':
            base = re.sub(r'(ing|ed|s)$', '', before)
            if previous.isspace() or before == 'else':
                value = 0.04
            elif before in QUESTION_VERBS or base in QUESTION_VERBS:
                value = 0.08
            elif before == 'as':
                value = 0.09
            elif before in {'only', 'or'}:
                value = -0.4
            else:
                value = -0.77
        elif prev == '(':
            value = -0.9
    elif word in {'si', 'se'}:
        boundary = (raw.startswith(' ') or not old_text
                    or not old_text[-1].isalpha())
        if boundary:
            lang = language(old_text)
            if word == 'si':
                value = {'fr': -0.9, 'es': -1.05}.get(lang, 0.0)
            else:
                value = {'it': -1.4, 'pt': -0.8}.get(lang, 0.1)
    elif word == 'nếu':
        value = -0.85
    elif word == 'если':
        value = -1.25 if token[:1].isupper() else -1.04
    elif text.lower().endswith('если') and not old_text.lower().endswith('если'):
        value = -1.4
    elif text.lower().endswith('якщо') and not old_text.lower().endswith('якщо'):
        value = -2.0
    elif any(b >= 128 for b in newest):
        # Longest completed marker wins; do not repeat it on a later token.
        matches = [m for m in CHINESE if text.endswith(m)
                   and not old_text.endswith(m)]
        if matches:
            marker = max(matches, key=len)
            value = CHINESE[marker]
            if marker == '即使' and token != marker:
                value = -15.0
        elif old_text.endswith('纵') and token.startswith('使'):
            value = -3.0
    return (doc, raw, count + 1, tail), value

programs.haiku:
"""Conditional and concessive connectives (negative), plus one corpus-specific spike.

The component goes strongly negative on words that open a concessive or conditional
clause, in English and Chinese (and some Spanish, French, Russian):
  * "even if", "即使", "即便", "就算", "哪怕", "纵使": the strongest, about -6 to -11;
  * "尽管", "不管", "儘管": medium; plain conditional "if" / "If" / "si" / "Если" /
    "如果" / "虽然": about -0.6 to -1.2; "though" is weaker, and more negative after "even".
"if" that asks a question ("see if", "check if") or is code (indented `if`) stays at 0.

Separately, a rare document-start quirk: a colon that is the second token of a
document whose first token is "Title" ("...<|endoftext|>Title: ...") spikes to +21.
Everything else is predicted as 0.
"""

READS = ()

INDIRECT_PREV = {"see", "check", "ask", "asked", "wonder", "know", "as", "else",
                 "whether", "determine", "test", "sure", "think", "tell", "find"}
# Chinese connectives: strongest first. Values are typical activations.
CHINESE = {"即使": -8.0, "即便": -8.0, "就算": -7.0, "哪怕": -8.0, "纵使": -8.0,
           "縱使": -8.0, "纵然": -6.0, "縱然": -6.0,
           "尽管": -2.4, "儘管": -2.4, "不管": -1.2, "無論": -0.6, "无论": -0.7,
           "除非": -1.4, "虽然": -0.8, "如果": -0.6, "若": -0.35, "要是": -0.2}
OTHER_LANGUAGE = {"si": -0.6, "если": -1.1}


def chinese_value(prev_tok, tok):
    for phrase, value in CHINESE.items():
        if phrase in tok or (prev_tok + tok).endswith(phrase):
            return value
    return None


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    prev_tok = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev = prev_tok.strip().lower()
    ids = prefix.document_ids
    title_starts_doc = len(ids) == 2 or (len(ids) > 2 and ids[-3] != ids[-2])
    value = 0.0
    zh = chinese_value(prev_tok, tok)
    if tok == ":" and prev_tok.strip() == "Title" and title_starts_doc:
        value = 21.0
    elif zh is not None:
        value = zh
    elif word.lower() in OTHER_LANGUAGE:
        value = OTHER_LANGUAGE[word.lower()]
    elif word.lower() == "if" and tok[:1] in (" ", "I"):
        if prev == "even":
            value = -5.0
        elif prev_tok.strip() == "" or prev in INDIRECT_PREV:
            value = 0.0
        else:
            value = -0.8
    elif word == "though":
        value = -0.6 if prev == "even" else -0.3
    return carry, float(value)

programs.sol:
"""Approximate plural-number signal from words and their endings.

An s-ending is stronger for dictionary nouns, weaker for common verb forms,
and stronger when the tokenizer splits off a suffix. Function words,
possessive tokens, singular s-endings and code abbreviations are suppressed.
Irregular English plurals and selected foreign plural/case suffixes also
respond. The first token gets a positive baseline, larger for capitals.
A document-initial
'Title:' label has a separate large negative colon response. The fixed
country name 'United States' is not treated as an ordinary plural.
"""
from functools import lru_cache
import re
import inflect
import wordnet
from wordfreq import zipf_frequency

READS = ()
_INFLECT = inflect.engine()
FUNCTION_WORDS = set('''is was has does as his this its us yes thus plus vs
perhaps always sometimes whereas towards across unless besides otherwise
ours yours hers theirs ourselves yourselves themselves
les des las los das dos os es als aus bis dans mais pas cos nos vos sus nas
mes tes ces ses vous nous tous très más tras fois depuis puis mas mis tus'''.split())
COMMON_VERBS = set('''be have do give make get take come go say seem become
look include contain require allow imply mean use want think tell keep wear
perform provide serve speak reach suggest mention consist belong relate'''.split())
PREFIXES = {'trans', 'dis', 'mis', 'dys'}
CODE_ABBREVIATIONS = {'js', 'ts', 'cs', 'rs', 'https', 'ps'}

@lru_cache(maxsize=50000)
def response(token, word):
    w = word.lower()
    continuation = bool(token) and token[0].isalpha() and word != token
    if w in {'data', 'media'}:
        return -0.2
    if w.endswith('们'):
        return -0.3
    if not w.endswith('s'):
        if 'noun' in wordnet.parts_of_speech(w):
            singular = _INFLECT.singular_noun(w)
            if singular and singular != w:
                return -0.6
        # Plural and oblique-plural endings in Slavic and Romanian words.
        if token in {
                'ов', 'ами', 'ями', 'ах', 'ях', 'ów', 'ů', 'ilor', 'elor'}:
            return -1.35
        if token in {
                'ы', 'ики', 'ки', 'ений', 'аний', 'ков', 'ات', 'ae'}:
            return -0.9
        if token in {'и', 'ей', 'ите', 'х', 'й', 'ий', 'ств', 'ungen'}:
            return -0.55
        if token in {'lar', 'ler', 'ları', 'leri', 'uri'}:
            return -0.7
        if continuation and token in {'i', 'e'}:
            return -0.45 if token == 'i' else -0.3
        return 0.0
    if len(word) > 2 and word.endswith('s') and word[:-1].isupper():
        return -2.6  # pluralized acronym
    if w in FUNCTION_WORDS or token.startswith(("'", '’')):
        return 0.0
    if w in CODE_ABBREVIATIONS or w in PREFIXES:
        return 0.0
    if w.endswith(('ss', 'ous', 'ness', 'sis', 'itis', 'us', 'is')):
        return 0.0
    if word.isupper() and len(word) <= 3:
        return 0.0
    if len(w) < 2:
        return -1.0 if token == 's' else 0.0
    if w in {'series', 'species', 'news'} or w.endswith('ics'):
        return -0.2 if not continuation else -1.1
    bases = wordnet.base_forms(w)
    pos = wordnet.parts_of_speech(w)
    if not continuation and w in bases:
        others = [b for b in bases if b != w]
        if not others or zipf_frequency(w, 'en') > max(
                zipf_frequency(b, 'en') for b in others) + 0.7:
            return -0.05
    strength = 0.55
    if 'noun' in pos:
        strength += 0.55
    if 'verb' in pos and ('noun' not in pos or any(
            b in COMMON_VERBS for b in bases)):
        strength = 0.35
    if continuation:
        strength += 0.5
        if len(token) == 1:
            strength += 0.3
    if word[:1].isupper():
        strength += 0.1
    if word.isupper():
        strength -= 0.3
    return -max(0.0, strength)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+\Z', tail + token, re.UNICODE)
    word = match.group() if match else ''
    value = response(token, word) if word else 0.0
    if first:
        initial = token.strip()[:1]
        value = 0.75 if initial.isupper() else 0.5 if initial.isalpha() else 0.25
    elif carry[2] and token == ':':
        value = -21.7
    elif tail == 'United' and word == 'States':
        value = 0.0
    return (doc, word[-50:], first and token == 'Title'), value

