                return 0.84
            return 1.94
    if word.startswith('highlight'):
        if word.endswith('s'):
            return 2.23
        return 3.08
    if word.startswith('lightning'):
        return 5.46
    if word.startswith('lighten'):
        return 5.11
    if word == 'lighter':
        return 2.92
    if word == 'lighting':
        return 1.34
    if word == 'lightweight':
        return 1.78
    if word == 'lightly':
        return 1.22
    if word.lstrip('._-/') in ('light', 'lights'):
        return 0.3 if word.endswith('s') else 0.61
    if word.startswith('brighton'):
