    if word in ('bright', 'brighter', 'brightest', 'brightness'):
        return 1.2 if word == 'brighter' else 0.62
    if word in ('overnight', 'nightly'):
        return 1.26 if word == 'overnight' else 3.02
    if word in ('night', 'nights'):
        return 0.2
    if word in ('twilight', 'freight', 'heavyweight', 'wright', 'leigh'):
        return 1.07
    if word in ('high', 'higher', 'highest', 'highly'):
        return 0.12 if word == 'high' else -0.11
    if word.startswith('ignite'):
