STEMS = re.compile(r'(?:^|[^a-z])(some|any|every|no|else) *([a-z]+)\Z')
ENDINGS = ('one', 'thing', 'body', 'where')
STRENGTH = {'some': 1.3, 'any': 0.7, 'every': 1.1,
            'no': 0.44, 'else': 1.1}


