    elif age == 1 and previous == '1' and token == '2':
        value = 2.29
    elif age == 1 and previous == 'Title' and token == ':':
        value = -2.39
    elif token == '2' and previous[-1:].isalpha():
        value = 0.15
    if token == '<|endoftext|>':
