    if t == ',':
        return 0.07 if nl else -0.02
    if t == ':':
        return -0.03
    return 0.05 if t == ';' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, line_length = 0, '', 0
    else:
        _, position, previous, line_length = carry
