        if '?' in t or '？' in t:
            value += 0.18 if line_length < 30 else 0.0
            value += 0.27 if previous.strip().lower() in INTERROGATIVES else 0.0
        elif '!' in t or '！' in t:
            value += 0.24 if line_length < 30 else 0.0
        elif t == '.' and len(previous.strip()) == 1 and previous.strip().isupper():
            value -= 0.08
    if not t and '\n' in s and previous.rstrip().endswith(tuple(STOPS)):
        value += 0.41
    line_length = len(s.rsplit('\n', 1)[-1]) if '\n' in s else line_length + len(s)
    return (doc, position + 1, s, line_length), value

"""Approximate a search/identification feature from words and short phrases.

The strongest signals are 'look for', 'search for', and 'see/check if'.
Smaller signals describe existence ('there is'), identifying actions, and
properties being counted or located ('presence/number/index of'). English
inflections use WordNet; Chinese search characters use OpenCC normalization.
Only a 100-character tail is kept, and it resets at document boundaries.
"""
import re
from functools import lru_cache
import wordnet
import opencc

READS = ()
SEARCH = set('look search check monitor watch scan browse listen hunt seek'.split())
PROBE = set('test assess evaluate analyze analyse survey screen inspect'.split())
QUERY = set('check verify detect determine wonder know understand ask test'.split())
EVIDENCE = set('presence absence existence abundance incidence identification '
               'evidence sign indication lack occurrence detection prevalence'.split())
AMOUNT = set('degree extent amount number quantity count fraction proportion '
             'percentage percent rate level magnitude concentration frequency'.split())
PLACE = set('index location position coordinate distance'.split())
ACTION = set('find identify locate detect determine discover uncover recognize '
             'observe assess seek remove exclude eliminate replace reveal'.split())
KNOWN = SEARCH | PROBE | QUERY | EVIDENCE | AMOUNT | PLACE | ACTION
KNOWN |= {'see', 'solve', 'compute', 'wait', 'filter'}
SIMPLIFY = opencc.OpenCC('t2s')


@lru_cache(20000)
def base(word):
    if word in KNOWN:
        return word
    return next((w for w in wordnet.base_forms(word) if w in KNOWN), word)


@lru_cache(10000)
def chinese(word):
    simple = SIMPLIFY.convert(word)
    if simple in {'寻', '寻找', '搜寻'}:  # Seek/search.
        return 5.0 if '尋' in word else 3.6
    return 2.1 if '找' in simple else 0.0  # Find.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    s, word = raw.lower(), raw.lower().strip()
    clause = re.split(r'[.!?;\n]', tail)[-1]
    words = re.findall(r'[a-z]+', clause)
    match = re.search(r'''([a-z]+)[\s'‘’“”"`]*$''', clause)
    previous = match.group(1) if match else ''
    prev = base(previous)
    before = words[-2] if len(words) > 1 else ''
    end = re.search(r'([a-z]+)$', tail + s)
    current = end.group(1) if end and s[-1:].isalpha() else ''
    root = base(current)
    value = 0.0

    if word in {'for', '_for'}:
        if prev in SEARCH:
            value = 6.3
            if prev in {'look', 'check', 'listen', 'monitor', 'watch'}:
                value = 5.5 if previous == 'looking' else 7.5
            if prev == 'check' and before in {'background', 'certified', 'your'}:
                value = 0.5  # A financial/background check is not searching.
            if prev == 'look' and before in {'unique', 'new', 'fresh'}:
                value = 1.0  # Appearance, rather than looking for something.
        elif prev in PROBE:
            value = 3.5 if previous.endswith('ed') else 1.5
        elif prev in {'solve', 'compute', 'wait'}:
            value = 2.3
        elif prev == 'filter':
            value = 6.0 if previous == 'filtering' else 1.0
        elif previous and any(base(w) in SEARCH for w in words[-5:]):
            value = 5.0 if previous in {'around', 'out', 'elsewhere'} else 2.5
    elif word == 'if':
        if prev == 'see':
            value = 5.3 if raw.startswith(' if') else 1.0
        elif prev in QUERY:
            value = 3.2 if prev == 'check' else 1.3
        elif previous in {'again', 'else'}:
            value = 1.5 if previous == 'again' else 0.65
    elif word in {'of', '_of'}:
        if prev == 'search':
            value = 3.7
        elif prev in EVIDENCE:
            value = 2.2 if prev in {'presence', 'absence', 'existence',
                                    'abundance', 'incidence', 'identification'} else 1.3
        elif prev in PLACE:
            value = 2.6 if prev == 'index' else 1.2
            if prev == 'index' and word == '_of':
                value = 5.0
        elif prev in AMOUNT:
            value = 1.0
            if prev in {'degree', 'extent'}:
                value = 2.7 if before == 'the' else 1.8
            elif prev == 'number':
                value = 0.5 if before in {'the', 'total'} else 0.2
            elif prev == 'amount':
                value = 1.25 if before == 'the' else 0.1
    elif word == 'there':
        value = 1.5 if previous in {'if', 'is'} else 0.1
    elif previous == 'there' and word in {'is', "'s", '’s', 'are', 'was', 'were'}:
        value = 0.9 if word in {'is', "'s", '’s'} else 0.45
    elif word == 'all' and prev == 'find':
        value = 2.5
    elif word == 'each' and previous in {'for', 'over'}:
        value = 3.1 if previous == 'over' else 0.5
    elif current == 'replace' and tail.endswith('str'):
        value = 1.35
    elif root in ACTION:
        value = 0.55
        if root == 'locate':
            value = 3.2 if current in {'locate', 'locates'} else 0.15
        elif root == 'identify':
            value = 1.9 if current in {'identify', 'identifying'} else 0.9
        elif root == 'find':
            value = 0.1 if current == 'found' else 0.65
        elif root == 'detect':
            value = 1.0
    elif root in EVIDENCE:
        value = 1.0 if root in {'presence', 'identification', 'detection'} else 0.3
    elif root in {'see', 'look'}:
        value = 0.7 if previous in {'me', 's', 'and'} else 0.3
    elif current == 'indexof':
        value = 2.2
    else:
        value = chinese(word)
    if word in {'for', 'of', 'if'} and raw.strip().isupper():
        value *= 0.4
    return (doc, (tail + s)[-100:]), value

"""Recognize hot/cold spellings, not a passage's actual temperature.

Large responses go to Chinese heat/cold roots and selected heat compounds,
Korean yeol, and fragment-completed fire emoji; English hot is weaker.
UTF-8 fragments are joined, with an extra response to the unfinished prefix
of 热. Separate rules cover chat delimiters at document starts and the th
in HTML table-header tags. Other tokens receive zero or a small baseline.
These surface rules do not capture arbitrary token-specific start effects.
"""

import codecs

READS = ()

# Heat used figuratively for enthusiasm or popularity.
HOT_FIGURATIVE = {'热心', '热点', '热门'}
START_MARKERS = {
    '<|im_start|>': 2.192,
    '<|im_end|>': 1.969,
    '<tool_call>': 1.98,
    '</tool_call>': 1.671,
    '<|endoftext|>': -1.315,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    pending, previous = (b'', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]

    # Decode just newly completed characters, not the preceding whole token.
    text = token
    fragmented = bool(pending) or '\ufffd' in token
    if fragmented:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        decoder.setstate((pending, 0))
        text = decoder.decode(raw)
        pending = decoder.getstate()[0]
    else:
        pending = b''
    state = (doc, pending, (previous + text)[-8:])

    if first and token in START_MARKERS:
        return state, START_MARKERS[token]
    if token == '<|im_start|>':
        return state, -0.023
    if token == '<|im_end|>':
        return state, 0.053
    if token == '</tool_call>':
        return state, 0.126

    word = text.strip()
    if word == '熱':
        return state, 5.7
    if word == '热':
        return state, 6.5 if fragmented else 4.0
    if pending == '热'.encode('utf-8')[:2]:
        return state, 6.4
    if word == '冷':
        return state, 3.1
    if word in HOT_FIGURATIVE:
        return state, 4.5
    if word in ('发热', '發熱'):
        return state, 4.3
    if '热' in word or '熱' in word:
        return state, 2.1 if len(word) <= 3 else 0.0
    if word == '열':
        return state, 5.2 if text.startswith(' ') else 1.0
    if fragmented and '🔥' in text:
        return state, 3.6
    if word.lower() == 'hot':
        if first:
            return state, 3.0
        return state, 0.5
    if word.lower() == 'ot' and previous.endswith(('h', 'H')):
        return state, 2.0 if word.isupper() else 0.8
    if word == 'nóng':
        return state, 1.3
    if word.lower() == 'thermal':
        return state, 0.25
    if word in ('温', '温度', '高温'):
        return state, 0.35
    if word == '寒冷':
        return state, 0.7
    if token == 'th':
        if previous.endswith('</'):
            return state, 4.5
        if previous.endswith('<'):
            return state, 3.7
    return state, 0.0

"""A modern-date prefix detector, firing negatively on the 9 of 19 or 0 of 20.

Temporal language and parentheses strengthen it; quantities, arithmetic and
line-number-like settings weaken it. Numeric-heavy documents also weaken it.
Chinese 一九 has the same, stronger response. Small secondary rules cover
initial digits, 20 inside longer numbers, and doubled backslashes in TeX/code.
No future digits are inspected: 19 and 20 need not actually become years.
"""
import calendar
import math
import regex as re

READS = ()
MONTHS = {m.lower() for m in (*calendar.month_name, *calendar.month_abbr) if m}
TEMPORAL = set(('in since from before after by during until dated late early '
                'mid circa around').split())
QUANTITY = set(('than over under about approximately roughly every exactly '
                'only above below consumes contains take takes equals is are '
                'was were of to for and').split())


def date_response(text, number, digits):
    """Estimate date-likeness from the text preceding the number."""
    words = re.findall(r'[a-z]+', text.lower())
    word = words[-1] if words else ''
    end = text.rstrip()[-1:]
    value = -1.9 + 0.2 * (number == '20') + 0.125 * math.log1p(digits)
    if re.search(r'\n[ \t]*$', text):
        value += 0.3
        if re.search(r'\n[ \t]{2,}$', text):
            value += 0.55
    elif text.endswith('['):
        value += 0.8
    elif text.endswith('('):
        value -= 0.4
    elif end and end in '-–—':
        value += 0.65
    elif text.endswith('/'):
        value += 0.2
    elif text.endswith('.'):
        value += 0.65
    elif text and text[-1].isalpha():
        value += 0.35
    elif not text or not text[-1].isspace():
        value += 0.65
    value -= 0.6 * (word in TEMPORAL)
    value -= 0.25 * (word in MONTHS)
    if word in QUANTITY:
        value += 0.6 if number == '20' else 0.2
    if re.search(r'[=+*^<>]|\\(?:frac|sqrt|sum|times|cdot)\b', text[-80:]):
        value += 0.5
    if re.search(r'\p{Script=Han}', text[-8:]):
        value -= 0.7
    if re.search(r'\b(year|born|copyright|century|date|published|died|circa)\b',
                 text[-80:].lower()):
        value -= 0.55
    if re.search(r'[A-Za-z_]\w*\($', text):
        value += 1.0
    return min(0.1, max(-3.4, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0, 0)
    _, text, run, before_number, digits, position = carry
    s = prefix.token_strings[-1]
    if not run:
        before_number = text
    run = run + s if s.isascii() and s.isdigit() else ''
    value = 0.0
    if run in ('19', '20'):
        value = date_response(before_number, run, digits)
    elif len(run) > 2 and run.endswith('20'):
        value = 0.4 if len(run) == 3 else 0.25
    if s == '九' and text.endswith('一'):
        value = -4.1
    if position == 0 and s in '01456789' and len(s) == 1:
        value = -0.28 if s == '0' else 1.6
    if '\\\\' in s:
        tex = re.search(r'\\(frac|begin|end|text|left|right|sqrt|quad|hline|'
                        r'mathrm|sum|int|nonumber|color)\b', text)
        value = 1.3 if tex else -0.75
    if run:
        digits += len(s)
    return (doc, (text + s)[-160:], run[-20:], before_number,
            digits, position + 1), value

"""Strong positive pulses for numeric indices attached to Latin letters.

A short capital label (A1, H3, MX1) or a one-letter variable (x1,
u_1, u_{1}) gives a positive pulse, strongest for small digits.
Later digits in the same index give a much smaller response. An underscore
after a single letter also gives a pulse. Byte escapes and hexadecimal
numbers are not treated as letter labels.
Fullwidth and typographic subscript digits use the same index rules.
A coarse negative baseline is used at document starts, with corrections
for source declarations, Title: metadata, and separator-only prefixes.
"""
import re
import unicodedata
from atoms import FULLWIDTH_DIGITS

READS = ()
LABEL = re.compile(r'(?<![A-Za-z0-9\\])([A-Za-z]+)([_^]\{?)?([0-9]*)\Z')
# Each row gives an offset, a digit-value slope, and an extra pulse for 1.
RESPONSES = {
    'ordinary': (0.006, -0.002, 0.003),
    'word': (0.058, -0.007, 0.027),
    'acronym': (0.11, -0.009, 0.082),
    'variable': (0.312, -0.022, 0.059),
    'subscript': (0.248, -0.031, 0.138),
    'spaced_capital': (0.293, -0.03, 0.048),
    'capital': (0.375, -0.023, 0.097),
}


def number_context(tail):
    spaced = tail.endswith(' ')
    m = LABEL.search(tail[:-1] if spaced else tail)
    if not m:
        return 'ordinary', 1.0
    word, subscript, digits = m.groups()
    if subscript:
        kind = 'subscript' if len(word) == 1 else 'word'
        gain = 1.0
    elif word.isupper():
        kind = 'capital' if len(word) <= 2 else 'acronym'
        gain = 1.0 if len(word) == 1 else 0.85
    else:
        kind = 'variable' if len(word) == 1 else 'word'
        gain = 1.0
    if spaced:
        if digits or not word.isupper() or len(word) > 2:
            return 'ordinary', 1.0
        kind = 'spaced_capital'
    if digits:
        gain *= 0.25 if len(digits) == 1 else 0.03
    return kind, gain


def activation(s, tail, position):
    if len(s) == 1 and s.isdigit() and (
        s in FULLWIDTH_DIGITS
        or unicodedata.name(s, '').startswith('SUBSCRIPT')
    ):
        s = unicodedata.normalize('NFKC', s)
        tail = unicodedata.normalize('NFKC', tail)
    if len(s) > 1 and not s.strip('·') and not tail.strip('·'):
        return -0.993
    if position == 0:
        if s in ('package', 'class', ' struct'):
            return {'package': 1.578, 'class': 0.436, ' struct': 0.698}[s]
        if s == 'Title':
            return -0.492
        if s[:1].isupper():
            return -0.32
        if s[:1].islower():
            return -0.25
        if s[:1].isspace():
            return -0.21
        return -0.155 if s.isdigit() else -0.10
    if s in '0123456789' and len(s) == 1:
        kind, gain = number_context(tail)
        a, b, c = RESPONSES.get(kind, (0.0, 0.0, 0.0))
        return gain * (a + b * int(s) + c * (s == '1'))
    if s == '_':
        m = LABEL.search(tail)
        if m and not m[2] and not m[3] and len(m[1]) == 1:
            return 0.23
    if s == ':' and position == 1 and tail == 'Title':
        return -4.529
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = activation(s, tail, position)
    return (doc, (tail + s)[-80:], position + 1), value

"""A short-spelling channel centred on K (and alphabetic K equivalents).

It is mostly silent. It gives negative responses to compact K spellings
such as king(s), Kent/Kirk, and kilo-unit abbreviations, and positive
responses to several short vowel continuations and Kubernetes spellings.
A separately tokenized K usually strengthens the response. Greek ka- has
its own positive response, including a following tau or theta. This is an
orthographic approximation, not a semantic category of K-initial words.
"""
import re
import unicodedata
from anyascii import anyascii

READS = ()
SEPARATORS = ' \t\n_./(-["\''


def spelling(text):
    """Keep Latin accents; romanize Cyrillic, Greek and Arabic letters."""
    out = []
    for c in text:
        name = unicodedata.name(c, '')
        if c != 'ъ' and any(s in name for s in ('CYRILLIC', 'ARABIC', 'GREEK')):
            c = anyascii(c)
        out.append(c)
    return ''.join(out)


def response(tail, split, capital, capitals, boundary):
    if re.fullmatch('ings?', tail):
        if split:
            return -12.0
        if capitals:
            return -9.0
        if capital:
            return -6.1
        return -4.7 if tail.endswith('s') else (-3.8 if boundary else -2.5)
    if tail in ('ent', 'irk'):
        return -7.2 if split else -3.4
    if tail in ('amp', 'ang', 'ong', 'ung', 'ungs'):
        return -5.0 if split else -3.0
    if tail == 'ingston':
        return -3.0
    if tail in ('gs', 'ms', 'wh'):
        return -7.5 if split else -2.5
    if tail == 'g':
        return -4.5 if split else -2.05
    if tail == 'm':
        return -4.5 if split else -0.85
    if tail == 'im':
        return -1.0
    if tail == 'ens':
        return -3.0 if split else -1.0
    if re.fullmatch('[aeou]m', tail):
        return -1.2
    if tail == '8':
        return 3.8
    if tail.startswith('ubernet'):
        return 1.0
    if tail == 'ubectl':
        return 2.6
    if tail == 'ube':
        return 4.5 if split else 3.3
    if tail == 'ath':
        return 5.1 if split else 1.7
    if tail == 'ab':
        return 4.3 if split else 0.9
    if tail in ('inn', 'ann', 'ian', 'na'):
        return 1.7 if split else 0.7
    if tail == 'ne':
        return 3.4 if split else 1.2
    if tail == 'ъ':
        return 2.0
    if tail == 'ids':
        return 0.8
    if (tail and tail[0] in 'áäéíóöőúüű' and len(tail) <= 2
            and not tail.endswith('r')):
        return 2.5 if split else 1.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, recent = ('', b'')
    if carry and carry[0] == document:
        previous, recent = carry[1:]
    raw = prefix.token_strings[-1]
    data = recent + prefix.token_bytes[-1]
    context = data.decode('utf-8', errors='replace')
    text = spelling(raw)
    carry = (document, text, data[-12:])

    # Greek kappa-alpha, and the common kat-/kath- continuations.
    if re.search('[κΚ][αά]$', context):
        return carry, 3.4
    if re.search('[κΚ][αά][τθ]$', context):
        return carry, 5.5
    if re.search('[κΚ]ιμ$', context):
        return carry, -5.0

    word = text.lstrip(SEPARATORS)
    split = False
    if word.startswith(('k', 'K')):
        tail = word[1:]
        capital = word[0] == 'K'
    elif (previous.lstrip(SEPARATORS) in ('k', 'K')
          and text[:1].isalnum()):
        tail, split = text, True
        capital = previous.endswith('K')
    elif previous.lower().endswith('k') and len(previous.strip()) <= 3:
        # Embedded final k has a weaker, selective continuation response.
        if text.lower() in ('g', 'gs', 'ms'):
            return carry, -4.0 if text.lower() == 'g' else -7.0
        if text in ('á', 'é', 'én', 'ív'):
            return carry, 2.5
        return carry, 0.0
    else:
        return carry, 0.0
    value = response(tail.lower(), split, capital, word.isupper(),
                     raw[:1].isspace())
    return carry, value

programs.haiku:
"""Layer-1 MLP output feature 2400: a 'K-word' detector.

Mostly silent. It goes strongly negative on the word "King" (and "Kings", "Kingston"),
most of all on capitalised uses such as "Martin Luther King" or "Stephen King"; weaker on
lowercase "king". It is also negative on the split-word pieces that spell K-names
("K" + "ing", "k" + "ent" for Kentucky, "k" + "irk" for Kirk), on the names Kirk and
Kling, and on the units "kg" and "km". It is weakly positive on the doubled middle dot
"··", and on Greek or Cyrillic k-letter words (κα + τ/θ, к + аб) and "K" + "ube"
(Kubernetes) and "k" + "8" (k8s). Everything else is 0.
"""

READS = ()

KING = {"king", "kings", "kingston"}
K_NAMES = {"kirk", "kent", "kling"}
UNITS = {"kg": -2.0, "/kg": -2.0, "km": -1.0}
K_LETTERS = {"k", "κ", "к"}          # Latin k, Greek kappa, Cyrillic ka
K_PIECES = {"ent": -7.0, "irk": -7.0, "ing": -10.0, "ings": -10.0, "ens": -3.0}
GREEK_PIECES = {"τ", "θ", "α"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    starts = len(prefix) == 1 or raw[:1] in (" ", "\n") or not raw[:1].isalnum()
    first = word[:1] if starts else (carry or "")  # first letter of the current word
    if raw == "··":
        return first, 0.6
    if word in KING:
        capital = raw.strip()[:1].isupper()
        return first, (-7.0 if capital else -3.5)
    if word in K_NAMES:
        return first, -3.5
    if word in UNITS:
        return first, UNITS[word]
    if prev in K_LETTERS and word in K_PIECES:
        return first, K_PIECES[word]
    if prev in K_LETTERS and word in ("ube", "8"):
        return first, 3.0
    if not starts and first in ("κ", "к") and word in GREEK_PIECES:
        return first, 2.5
    return first, 0.0

programs.sol:
"""A sparse, boundary-sensitive lexical approximation, not a single topic flag.

High-importance examples suggested government/administration vocabulary across
Chinese, Korean and Vietnamese, and English 'administrative'. The rules also
cover celebration/phoenix characters, choice words, romanized syllable endings,
and 'what type of'. Compounds need their own amplitudes, not character sums.
A weak initial-capitalization bias and a chat-start marker handle some document
starts. All other positions get zero; much context-dependent variation remains.
"""

READS = ()

# Chinese government terms: government, State Council, and local governments.
GOVERNMENT = {'政府': -3.2, '人民政府': -7.0, '国务院': -5.5,
              '区政府': -4.5, '市政府': -4.5, '县政府': -4.5,
              '中国政府': -2.4, '当地政府': -2.0}
# Administration, finance, policy, and party rule.
ADMINISTRATION = {'行政': -2.7, '财政': -2.5, '政策': -1.8,
                  '新政': -1.8, '党政': -3.2, '执政': -1.7,
                  '行政机关': -1.3, '行政处罚': -1.4}
# Politics, government office, phoenix, and celebration characters/words.
CHARACTERS = {'政': -3.7, '府': -4.8, '凤': -3.6,
              '庆': -2.2, '慶': -2.2, '凤凰': -1.5}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
