programs.sol:
"""A Chinese indefinite-quantity response.

'One item', 'some', and 'one kind' receive large negative values. Other
noun classifiers receive smaller negative values. Ordinals and definite
phrases are mostly spared. Counts of bodily actions and spatial sides,
and non-classifier characters completing a split 'one ...', are positive.
Vietnamese 'một' (one/a) has a small negative response. The remaining
activation variation is not modeled. Traditional forms are normalized;
Japanese context weakens the Chinese quantity rules.
"""
from functools import lru_cache
import cedict
import opencc
import regex

READS = ()
_CONVERT = opencc.OpenCC('t2s')
_KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
_HAN = regex.compile(r'\A\p{Han}\Z')
# These common adverb/pronoun compounds are not indefinite noun phrases.
LEXICALIZED = {'一起', '一下', '一样', '一般', '一切', '一番', '一度'}

@lru_cache(maxsize=65536)
def normalize(text):
    return _CONVERT.convert(text.strip())

@lru_cache(maxsize=8192)
def noun_classifier(text):
    return any('classifier' in gloss.lower() for gloss in cedict.glosses(text))

@lru_cache(maxsize=65536)
def estimate(text, previous):
    s, p = normalize(text), normalize(previous)
    if s in LEXICALIZED:
        return 0.05
    if s == 'một':
        return -0.62
    if s[:1] in '第每同另下上这那' and '一' in s:
        return 0.001
    for head, bare, modified in [('些', -3.8, -3.0),
                                 ('种', -3.2, -2.7),
                                 ('个', -1.8, -1.6)]:
        if s.endswith('一' + head):
            return modified if s[:-2] else bare
    if len(s) == 2 and s[0] == '一':
        if s[1] in '眼脚拳掌':
            return 2.4
        if s[1] in '边面方侧':
            return 1.1
    if len(s) >= 2 and s[-2] == '一' and noun_classifier(s[-1]):
        return -0.74
    if s in ('的一', '了一', '是一', '在一'):
        return -0.87
    if s in ('有些', '这些', '那些', '某些'):
        return -0.32
    if s in ('这种', '那种', '某种', '各种', '此类',
             '这类', '那类', '此种', '何种'):
        return -0.74
    if s in ('这个', '那个', '某个', '各个', '每个', '几个', '哪个'):
        return -0.28
    if _HAN.fullmatch(s):
        definite = p.endswith(('统一', '唯一', '同一', '每一', '另一'))
        if p.endswith('一') and not definite:
            if s in '些种个':
                return {'些': -4.6, '种': -3.5, '个': -1.7}[s]
            return -1.05 if noun_classifier(s) else 0.8
        if p[-1:] in '这那某各此几两' and p and s in '个些种':
            return -0.9 if s == '种' else -0.35
    if s == '些':
        return -2.3
    return 0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, recent = ('', '')
    if carry and carry[0] == document:
        previous, recent = carry[1:]
    text = prefix.token_strings[-1]
    value = estimate(text, previous)
    if value < -0.1 and _KANA.search(recent + text):
        value *= 0.3
    return (document, text, (recent + text)[-24:]), value

"""Approximate a local law/laws spelling feature, not general legal subject matter.

Legal relatives, selected translations, and fragments completing these words
also give positive pulses. Case, token joins, and nearby function words adjust
the strength; some common scientific-law phrases are weaker. We also predict
'of' after law(s), negative 'aw' fragments outside law, and the document-initial
'Title:' spike. Everything else is zero. State resets at document boundaries.
"""
import re

READS = ()

# Whole-token relatives of 'law', with their weaker responses.
RELATIVES = {
    'legal': 1.2, 'legally': 0.9, 'legality': 0.7,
    'illegal': 1.1, 'lawful': 2.8, 'unlawful': 3.3,
    'unlaw': 2.9, 'outlaw': 3.1, 'lawyer': 0.6, 'lawyers': 0.3,
    'flaw': 1.0, 'flaws': 1.0, 'flawed': 1.0, 'flawless': 0.7,
    'claw': 1.0, 'claws': 1.0, 'lawn': 3.0,
}
# Romance-language forms of 'law' (including Romanian 'lege').
TRANSLATIONS = {'ley': 7.0, 'leyes': 10.0, 'loi': 5.0, 'lois': 8.0,
                'lei': 3.3, 'leis': 8.0, 'legge': 7.0, 'leggi': 5.0,
                'lege': 4.5}


COMPLETIONS = {
    'loi': 8.5, 'lois': 10.0, 'leyes': 11.7,
    'leis': 9.3, 'legge': 8.1, 'leggi': 5.2, 'lege': 4.5,
    'legale': 4.2, 'legali': 4.2, 'legales': 6.6,
    'légale': 1.5, 'légales': 1.5, 'legis': 4.5,
    'lawful': 7.0, 'lawfully': 4.0, 'unlawfully': 3.6,
}


FRAGMENTS = {w[i:] for w in (*COMPLETIONS, 'law', 'laws')
             for i in range(1, len(w))}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    joined = tail + token
    value = 0.0
    if lower in {'law', 'laws', '-law'}:
        if word.isupper():
            value = 7.8
        elif lower == 'laws':
            value = 5.4 if token.startswith(' ') else 8.0
        elif word.istitle():
            value = 4.8
        else:
            value = 4.4 if token.startswith(' ') else 7.2
        modifier = previous.strip().lower()
        # Common scientific-law phrases are much weaker than legal 'law'.
        if modifier == 'power':
            value = 2.1
        elif modifier in {'first', 'second', 'third', 'zeroth', 'conservation'}:
            value = 0.4
        elif token.startswith(' '):
            if modifier in {'by', 'in'}:
                value += 2.1
            elif modifier in {"'s", '’s', 'this', 'that', 'these', 'those'}:
                value -= 1.5
    elif lower in RELATIVES:
        value = RELATIVES[lower]
        if lower == 'illegal' and word[0].isupper():
            value = 0.0
    elif lower in TRANSLATIONS:
        value = TRANSLATIONS[lower] if token.startswith(' ') else 0.3
        if lower == 'loi' and not token.startswith(' '):
            value = 1.6
    elif word in {'法律', '법', '법률'}:
        value = 1.1
    elif word == '法':
        value = 0.2
    elif token.isalpha() and token.lower() in FRAGMENTS:
        end = joined.lower()
        if end.endswith(('law', 'laws')):
            if joined[-4:].isupper() and end.endswith('laws'):
                value = 15.5
            else:
                value = 12.0 if token.lower().endswith('aws') else 9.0
        else:
            match = re.search(r'[^\W\d_]+$', tail, re.UNICODE)
            stem = match[0] if match else ''
            completed = (stem + token).lower()
            value = COMPLETIONS.get(completed, 0.0)
            if completed == 'leis' and stem.istitle():
                value = 3.5
    # The same fragment away from an L is usually slightly negative.
    if token == 'aw' and not tail.lower().endswith('l'):
        value = -3.5 if tail[-1:].lower() in {'e', 'i'} else -0.5
    if token == ' of':
        if tail.lower().endswith('laws'):
            value = 5.1
        elif tail.lower().endswith('law'):
            value = 3.0
    if token == ':' and tail == 'Title':
        value = 5.9
    return (doc, joined[-32:], token), value

programs.haiku:
"""Law-word detector. The component fires on the token that completes a word meaning
'law' (law, laws, Law; hyphenated -law as in 'son-in-law'; Spanish 'ley'/'leyes', French
'lois'/'loi', Italian 'legge', Chinese 法律), more weakly on 'legal'-type words, and on the
' of' right after 'law'/'laws' ('laws of demand'). It is silent elsewhere."""
READS = ()

LAW_WORDS = {"law", "laws", "lois", "loi", "leyes", "legge"}   # words, incl. split 'lo'+'is'
HYPHEN_LAW = 10.0                                           # '-law' in 'son-in-law'
LAW_ACT = 5.0
LEGAL_WORDS = {"legal": 1.2, "illegal": 1.3, "unlawful": 1.0, "legally": 1.0}
FOREIGN = {"法律": 1.3, " ley": 5.0}
OF_AFTER_LAW = 3.7


def trailing_word(text):
    """The letters ending the decoded text so far (lowercase), e.g. 'lois' after 'lo' + 'is'."""
    word = ""
    for ch in reversed(text.lower()):
        if not ch.isalpha():
            break
        word = ch + word
    return word


def is_law(token):
    return token.strip(" -").lower() in LAW_WORDS


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "-law":
        return None, HYPHEN_LAW
    if is_law(token) or token in FOREIGN:
        return None, FOREIGN.get(token, LAW_ACT)
    if token == " of" and len(prefix.token_strings) > 1 and is_law(prefix.token_strings[-2]):
        return None, OF_AFTER_LAW
    word = trailing_word(prefix.text_prefixes[-1])
    if word in LAW_WORDS or (word.endswith("law") and word not in {"flaw", "claw", "slaw"}):
        return None, LAW_ACT
    return None, LEGAL_WORDS.get(word, 0.0)

programs.sol:
"""A local detector for unspecified things and 'what' constructions.

The main responses are negative: thing(s), indefinite thing-pronouns,
translations of those expressions, and the grammatical continuation of
'what'. Modifiers distinguish 'first/only thing' from an ordinary 'thing'.
These local rules approximate common uses, not complete syntax or meaning.
Levels are rounded estimates from training text. A 480-byte tail handles split words
and resets at document boundaries; other tokens get a near-zero value.
"""
import re

READS = ()

# Typical levels for indefinite thing-pronouns, fitted on training text.
INDEFINITES = {
    'something': -1.42, 'anything': -1.65, 'everything': -0.91,
    'nothing': -0.78, 'whatever': -0.46,
}

LETTERS = re.compile(r"[^\W\d_]+", re.UNICODE)
GERMAN = re.compile(
    r"\b(?:und|der|die|das|ein|eine|ist|nicht|für|mit|auch|sich|auf|zu|"
    r"den|dem|des|ich|wir|Sie)\b"
)
POLISH = re.compile(r'[ąćęłńóśźżěščřžďťů]')
ENGLISH = {'the', 'and', 'of', 'to', 'a', 'he', 'it', 'his', 'with', 'that'}
FRENCH = re.compile(
    r'\b(?:le|la|les|de|du|des|une|un|que|qui|ce|et|est|en|pour|'
    r'dans|par|pas)\b'
)


def expression(token, before, position):
    """Predict from the expression ending at this token, not future text."""
    text = before + token
    words = LETTERS.findall(before)
    prev = words[-1].lower() if words else ''
    prev2 = words[-2].lower() if len(words) > 1 else ''
    m = LETTERS.search(text[::-1]) if text and text[-1].isalpha() else None
    word = m[0][::-1] if m and m.start() == 0 else ''
    w = word.lower()
    s = token.strip().lower()
    capital = word[:1].isupper()

    # The question word often gives its largest response one token later.
    question = prev == 'what' and bool(re.search(r'what\s*$', before, re.I))
    if prev in {'exactly', 'precisely', 'actually', 'really', 'then'}:
        question = prev2 == 'what' and bool(
            re.search(r'what\s+\w+\s*$', before, re.I)
        )
    if question:
        if s in {"'s", '’s'}:
            return -6.8 if words[-1] == 'What' else -5.03
        if w in {'exactly', 'precisely'}:
            return -7.05
        if prev2 == 'what' and w in {'is', 'do', 'does'}:
            return -4.97
        if w in {'do', 'does', 'did', 'is', 'are', 'was', 'were', 'can',
                 'could', 'would', 'will', 'should', 'might', 'shall', 'to'}:
            if position == 1 and w in {'is', 'do', 'does'}:
                return -15.45 if before == 'What' else -8.5
            if w in {'do', 'does'}:
                return -9.98
            if w == 'is':
                return -3.97 if words[-1] == 'What' else -2.63
            if w in {'are', 'was', 'were'}:
                return -2.43
            if w == 'to':
                return -5.07
            return -5.49
        if w in {'i', 'you'}:
            return -2.74
        if w in {'we', 'they', 'he', 'she', 'it'}:
            return -1.55
        if w in {'kind', 'type', 'sort'}:
            return 2.02
        if w == 'else':
            return -10.25

    if re.search(r"what\\?['’]s$", text, re.I):
        return -5.03
    if w == 'whats':
        return -5.03

    indefinite = INDEFINITES.keys()
    if w == 'else' and prev in indefinite:
        return -4.87
    if w == 'to' and prev in indefinite | {'thing', 'things', 'more', 'much'}:
        if prev == 'thing' and prev2 in {'first', 'only', 'last', 'best', 'one'}:
            return -5.7
        return -2.87
    if w == 'that' and prev in indefinite | {'thing', 'things'}:
        return -2.25

    if w in {'thing', 'things'}:
        if prev == 'first':
            return -12.7 if w == 'thing' else -8.88
        if w == 'thing' and prev == 'the':
            return -0.84
        if w == 'things' and prev == 'the':
            return -4.58
        if prev in {'only', 'last', 'next', 'best', 'worst',
                    'main', 'important', 'another'}:
            return -8.21 if w == 'thing' else -5.47
        if prev in {'one', 'other', 'many', 'few', 'more', 'two', 'three', 'all'}:
            return -7.33 if w == 'thing' else -4.58
        if token[:1].isspace():
            return -3.46 if w == 'thing' else -2.45
        return -2.68
    if w in indefinite:
        if w == 'everything' and capital:
            return -1.7
        if prev in {'is', 'are', 'was', 'be', 'there'}:
            return -1.92 if w == 'anything' else -1.62
        return INDEFINITES[w]
    if w == 'what':
        if position == 0:
            return 3.4
        if capital:
            return 0.1
        if prev in {'is', 'was', 's'}:
            return -1.84
        if prev in {'of', 'about', 'on', 'in', 'for', 'at', 'over', 'with'}:
            return -1.55
        return -0.48

    # Romance nominal relatives: ce que/qui, lo que, o que.
    if w == 'dont' and prev == 'ce':
        return -7.05
    if (w in {'que', 'qui', 'qu', 'che'} and
            prev in {'ce', 'lo', 'o', 'ciò'} and prev2 not in {'à', 'est'}):
        return -7.05
    if w in {'chose', 'choses'} and (w == 'choses' or FRENCH.search(before)):
        return -5.37
    if ((word.islower() or word.istitle()) and
            w in {'cosa', 'cosas', 'cose', 'coisa', 'coisas', 'qualcosa'}):
        return -7.23
    if w == 'algo' and (capital or token[:1].isspace()):
        return -6.19
    if w in {'quoi', 'hvad', 'vad'}:
        return -1.81
    if w in {'cela', 'ça', 'isso', 'rien', 'nada', 'nichts', 'etwas', 'tutto'}:
        return -2.76
    german_count = len(GERMAN.findall(before))
    english_count = sum(x.lower() in ENGLISH for x in words)
    if w == 'was' and (german_count > english_count or
                       prev in {'alles', 'etwas', 'das'}):
        return -5.82
    if w == 'wat':
        return -1.96
    if w in {'czego', 'czym', 'czegoś'}:
        return -9.13
    if w in {'čo', 'čeho', 'něco', 'něčeho'}:
        return -7.13
    if w == 'co' and POLISH.search(before):
        return -4.31

    if w == 'что':
        if prev == 'потому':
            return -0.74
        return -9.47 if capital else -4.14
    if w in {'чему', 'чём'}:
        return -9.95
    if w in {'ничто', 'нечего'} or word == 'Ничего':
        return -12.22
    if w in {'ничего', 'нечто', 'чего', 'чем', 'прочего'}:
        return -3.39
    if w == 'то' and re.search(r'что-$', before):
        return -9.0
    if w in {'що', 'какво', 'това', 'което'}:
        return -5.87
    if word == 'yang':
        return -1.39
    if token.startswith('こと'):
        return -1.85
    if token.endswith('こと'):
        return -2.17
    if w in {'gì', 'điều'}:
        return -2.26
    if s in {'什么', '甚麼', '什麼'}:
        return -0.53
    return -0.0041


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0)
    _, tail, position = carry
    token_bytes = prefix.token_bytes[-1]
    before = tail.decode('utf-8', errors='replace')
    token = token_bytes.decode('utf-8', errors='replace')
    # Decode together to recover characters split across byte tokens.
    joined = (tail + token_bytes).decode('utf-8', errors='replace')
    if '\ufffd' in token:
        token = joined[len(before.rstrip('\ufffd')):]
        before = before.rstrip('\ufffd')
    value = expression(token, before, position)
    return (doc, (tail + token_bytes)[-480:], position + 1), value

