"""Candidate v6: words meaning 'a thing / what', across languages, and the
token right after a 'what' or 'thing' word, plus free-relative 'what' clauses."""
READS = ()
THING_WORDS = {
    "thing": -4.0, "things": -3.0, "cosa": -8.0, "что": -4.0, "cela": -3.5,
    "chose": -2.0, "etwas": -2.7, "こと": -2.7, "tutto": -2.4, "isso": -2.4,
    "чего": -3.4, "ничего": -5.0, "чем": -2.2, "то": -1.0, "algo": -2.5,
    "nada": -2.5, "tudo": -2.5, "something": -1.5, "anything": -1.5,
    "everything": -1.0, "nothing": -1.0, "alles": -1.1,
}
WHAT_PRONOUNS = {"que", "qui", "quoi", "was", "co", "what", "что", "cosa", "chose"}
FREE_RELATIVE_LEADS = {"lo", "ce", "alles", "nothing", "something", "everything", "all"}
ORDINAL = {"first", "one", "only", "same", "other", "such", "next", "last", "best", "another"}
WH_AUX = {"do", "does", "did", "can", "could", "will", "would", "to", "'s", "else", "that"}
AFTER_WH = {"is", "are", "was", "were", "you", "i", "they", "we", "he", "it", "she"}
PREV_THING = {"what", "thing", "things", "something", "anything", "nothing"}
BREAK = {"", ".", "?", "!", '"', "\n"}

def norm(s):
    return s.strip().lower().replace("’", "'")

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = norm(toks[-1])
    prev = norm(toks[-2]) if len(toks) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    if cur in THING_WORDS:
        value = THING_WORDS[cur] * (2.5 if prev in ORDINAL else 1.0)
    elif cur in WHAT_PRONOUNS and prev in FREE_RELATIVE_LEADS:
        value = -5.0
    elif prev == "what":
        value = -6.5 if cur in WH_AUX else (-3.0 if cur in AFTER_WH else 0.0)
    elif prev in PREV_THING:
        value = -3.0 if cur in WH_AUX else (-1.0 if cur in AFTER_WH else 0.0)
    elif cur == "what":
        value = 0.0 if (prev in BREAK or prev.endswith("\n")) else -0.7
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Lexical cues for a reference time or stage: now, then, and so far.

The strongest cues are completed phrases: 'so far', 'right now',
'at this point', and 'to date'. Ordinary uses of the same nouns are
mostly quiet. The short carry only remembers enough text for these
phrases, and is reset at document boundaries. Several translations of
now/past/current time and the contrasting phrase 'or otherwise' are
also recognized. Other tokens are mostly assigned zero; incidental
word-piece responses are not modeled. Values approximate training means.
"""
import re

READS = ()

# Temporal words whose last piece can arrive as a separate token.
COMPLETED_TIME_WORDS = {
    'agora': 4.8, 'ahora': 3.5, 'adesso': 4.8, 'maintenant': 3.8,
    'hitherto': 4.6, 'henceforth': 3.3, 'finora': 4.1,
    '과거': 5.0, '이제': 2.7, '지금': 2.8,
}


def response(s, before):
    w = s.strip().lower()
    words = re.findall(r"\w+|[^\w\s]", before.lower())[-3:]
    # Previous word/punctuation, and the one before it.
    p = words[-1] if words else ''
    q = words[-2] if len(words) > 1 else ''

    if s[:1].isalpha() and before[-1:].isalpha():
        completed = p + w
        if completed in COMPLETED_TIME_WORDS:
            return COMPLETED_TIME_WORDS[completed]
        if completed == 'hiện':  # Vietnamese: present/current
            return 11.0 if before.endswith('Hi') else 2.0

    if w == 'now':
        if p == 'right':
            return 7.2
        if p in {'by', 'until', 'till', 'so'}:
            return 5.0
        if p in {'but', 'for'}:
            return 3.4
        if s.strip() == 'Now':
            return 1.5
        return 1.8
    if w == 'far':
        if p in {'so', 'thus'}:
            return 10.0 if q in {'.', ','} else 8.5
        return 2.4 if p == 'by' else 0.02
    if w == 'date':
        if p == 'to':
            return 3.1 if q == 'up' else 6.2
        if q in {'of', 'at', 'to'} and p in {'this', 'that', 'the'}:
            return 1.9
        return 0.03
    if w == '-date' and before.lower().endswith('up-to'):
        return 2.2
    if w in {'point', 'time', 'stage', 'moment'}:
        if p in {'this', 'that', 'which', 'the'}:
            if q in {'at', 'by', 'to', 'from', 'in'}:
                if w == 'point':
                    if p == 'this':
                        return 7.0 if q in {'at', 'by'} else 5.3
                    if p == 'that' and q in {'at', 'by'}:
                        return 3.8
                    return 3.3 if p == 'which' and q == 'at' else 0.1
                if w == 'stage':
                    return 4.5 if p == 'this' else 0.6
                if w == 'moment':
                    return 4.7 if p == 'this' and q == 'at' else 1.6
                if q in {'at', 'by'}:
                    return 2.2 if p == 'the' else 3.5
        return 0.04
    if w == 'present':
        if p == 'at':
            return 6.3
        if q == 'at' and p == 'the':
            return 3.0
        return 0.46 if p == 'the' else -0.05
    if w == 'first' and p == 'at':
        return 3.0
    if w == 'then':
        if p == 'because':
            return 1.0
        if p in {'since', 'until', 'till', 'back', 'just', 'right', 'by'}:
            return 2.7
        if p == 'even':
            return 2.0
        # Temporal 'was then' versus connective ', then'.
        if p in {'was', 'were', 'so'}:
            return 0.9
        if p in {'he', 'she', 'it', 'we', 'i', 'they', 'you'}:
            return 0.6
        if p in {'but', 'is', 'are', 'can', 'will', 'would'}:
            return 0.4
        return -0.25 if p in {',', ';'} else -0.04
    if w == 'that' and p == 'now':
        return 3.0
    if w in {'this', 'that'} and p == 'at':
        return 1.2
    if w == 'current':
        if p == 'at' or (p == 'the' and q == 'at'):
            return 3.5
        if p in {'the', 'my', 'our', 'its', 'his', 'her', 'their'}:
            return 1.2
        return 0.35
    if w == 'existing':
        return 0.39
    if w in {'currently', 'presently'}:
        return 1.7 if s.strip()[:1].isupper() else 0.95
    if w == 'away' and p == 'right':
        return 3.2
    if w == 'there':
        if p == 'out':
            return 1.4
        if p == 'right':
            return 3.1
    if w == 'here':
        return 0.18
    if w == 'longer' and p == 'no':
        return 0.68
    if w in {'otherwise', 'other'} and p == 'or':
        return -2.6 if w == 'otherwise' else -1.0

    # Chinese and Japanese words for now / the present / that time.
    if w in {'目前', '目前为止', '现在', '現在', '现在的'}:
        if before.endswith(('实', '實', '表', '展')):
            return 0.0
        return 3.2 if w == '现在的' else 5.2
    if w == '在' and before.endswith(('现', '現')):
        return 8.5
    if w in {'时', '時'} and before.endswith(tuple('当當那这這此现現到即')):
        return 3.2
    if w == '刻' and before.endswith(tuple('即此时時')):
        return 3.3
    if w in {'下', '下的'} and before.endswith(tuple('当當时時')):
        return 3.4
    if w == '今' and before.endswith('現'):
        return 3.8
    if w in {'现有', '现有的'}:
        return 3.2
    if w in {'到现在', '我们现在', '这个时候', '迄今为止'}:
        return 2.5
    if w in {'此时', '此刻', '当时', '當時', '那时', '那个时候'}:
        return 3.6
    if w in {'当前', '当下', '如今', '这时', '迄今', '截至目前'}:
        return 2.2
    if w in {'今', '现', '現', 'いま'}:
        return 2.2 if w == '现' else 1.4
    # Several other languages' equivalents of "now" and "so far".
    if w == 'ora' and not s[:1].isspace() and before[-1:].isalpha():
        return 0.3
    if w in {'ahora', 'agora', 'ora', 'maintenant', 'jetzt',
             'сейчас', 'теперь', 'الآن', '지금'}:
        return 5.0 if p in {'bis', 'hasta'} else 2.5
    if w == 'présent' and p == 'à':
        return 5.7
    if w == 'hiện':
        return 7.8 if s.strip()[:1].isupper() else 1.0
    if w == 'tại' and p == 'hiện':
        return 3.7
    if w in {'này', 'đó', 'ấy', 'nào'} and p in {'lúc', 'khi'}:
        return 3.5
    if w == 'giờ' and p in {'bây', 'đến'}:
        return 4.0
    if w == 'пор' and p == 'сих':  # Russian: up to now
        return 4.1
    if w == 'ini' and p == 'saat':  # Indonesian: currently
        return 3.5
    if w in {'현재', '현재의'}:
        return 3.0
    if w in {'bisher', 'entonces'}:
        return 3.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_bytes[-1]
    # Decode joined bytes so a token may finish a multi-byte character.
    text = before.decode('utf-8', errors='ignore')
    extended = (before + token).decode('utf-8', errors='ignore')
    value = response(extended[len(text):], text)
    return (doc, (before + token)[-100:]), value

programs.haiku:
"""Line-break detector (layers.1.mlp.down_proj, component 2410).

This component writes into the residual stream when the text reaches the end of a line.
It fires on the newline token itself, and on an escaped newline written as a backslash
followed by "n" (as in code strings). How strongly it fires depends on the characters just
before the break:

- a bare line break, or one after code punctuation (`,` `;` `)` `:` quote, bracket, tab),
  is strong (about 0.7 to 1.1);
- a break after a table-like mark (`|` `/` `%` `+`) is the strongest;
- the first token of a packed row sits slightly above zero;
- a blank line (two breaks in a row) is moderate (about 0.4 to 0.6);
- a break after a sentence end (`.` `!` `?`) is weak (about 0.1);
- a break after a closing brace followed by a blank line is slightly negative.

Every other token gives 0. The values are rough class means fitted on training text.
"""

READS = ()

SENTENCE_END = set(".!?。")
TABLE_MARKS = set("|/%+*-")
ESCAPED_NEWLINE = 0.4  # "\n" written as backslash and n inside code
ROW_START = 0.2  # activation at the first token of a row (mean about 0.22)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) == 1:  # the first token of a packed row: a small constant bump
        return carry, ROW_START
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token == "\\n" or (token == "n" and before == "\\"):
        return carry, ESCAPED_NEWLINE
    if "\n" not in token:
        return carry, 0.0

    body = token.rstrip("\r\n")  # the text before the line break(s)
    double = token.count("\n") >= 2  # a blank line
    if body == "":
        if token == "\n":
            return carry, 1.1
        return carry, (0.6 if double else 1.2)
    last = body[-1]
    if last in SENTENCE_END:
        return carry, (0.1 if double else 0.15)
    if last == "}":
        return carry, (-0.15 if double else 0.35)
    if last in " \t":
        return carry, (0.4 if double else 0.5)
    if last in TABLE_MARKS:
        return carry, (0.45 if double else 1.4)
    return carry, (0.45 if double else 0.75)

programs.sol:
"""A sparse predictor of spelling and token-boundary responses.

A document opening with separate tokens 1, 2 gets a large positive value
on 2. Particular UTF-8 splits give signed responses: Hiragana after し
(especially つ/ず), 桜, ℤ, flag letters, and C2 after non-ASCII fragments.
Doubled middle dots are positive. Initial comment markers, single ASCII
letters, and whitespace have separate baselines; everything else is near
zero. These local rules capture some sharp responses, not most activity.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        position, previous, first = 0, b'', token
    else:
        _, position, previous, first = carry
    value = 0.001
    if position == 1 and first == b'1' and token == b'2':
        value = 5.76
    elif (token == b'\xc2' and previous and
          (previous[-1] >= 0x90 or
           (len(previous) > 1 and previous[-1] >= 0x80))):
        value = 0.9
    elif len(token) == 1 and 0x80 <= token[0] < 0xC0:
        if previous == 'し'.encode() + b'\xe3\x81':
            ending = (b'\xe3\x81' + token).decode('utf8', 'replace')
            if ending == 'つ':
                value = -5.5
            elif ending == 'ず':
                value = -5.9
            else:
                value = -0.9
        elif previous == b'\xe6\xa1' and token == b'\x9c':  # 桜
            value = 2.7
        elif previous.endswith(b'\xe2\x84') and token == b'\xa4':  # ℤ
            value = -1.7 if previous.startswith(b' ') else -1.2
        elif previous == b' \xf0\x9f' and token == b'\x87':
            value = -2.0  # Regional-indicator letters used in flags.
    elif token == '··'.encode():
        value = 0.95
    if position == 0:
        if token == b'//\n':
            value = 2.69
        elif token.startswith((b'#', b'/*', b'//')):
            value = 0.6
        elif len(token) == 1 and token.isalpha():
            value = -0.24
        elif token == b'\t':
            value = 0.84
        elif token.isspace():
            value = -0.3
    return (doc, position + 1, token, first), value

"""A spelling-based approximation for n/ny subword continuations.

Negative responses follow written ny, especially the Indonesian ending -nya,
short n + ya/ye/yi/yo syllables, and Hungarian ny. Recent complete function
words and Hungarian double-acute vowels provide language evidence. Longer
pieces containing -nya get a weaker suffix response. Short men-/pen- pieces
have a positive non-y continuation response. Two English 'many' constructions
and a document-opening Title: label are handled separately. Small unrelated
token-specific fluctuations are not modeled.
"""
import unicodedata

READS = ()
INDONESIAN = frozenset(('yang', 'dan', 'dengan', 'untuk', 'tidak', 'ini',
                       'itu', 'dari', 'pada', 'dalam', 'juga', 'akan',
                       'oleh', 'adalah'))
HUNGARIAN = frozenset(('hogy', 'egy', 'és', 'nem', 'az', 'meg', 'vagy', 'volt'))


def fold(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, word, ind, hun, position = '', '', 0., 0., 0
    else:
        _, prev, word, ind, hun, position = carry
    oldword = fold(word)
    s = prefix.token_strings[-1]
    low, text, previous = s.lower(), fold(s), fold(prev)
    ind *= .985
    hun *= .985
    # Assemble words, so a function word split across tokens still counts.
    for char in s:
        if char.isalpha():
            word = (word + char)[-64:]
        else:
            ind += word in INDONESIAN
            hun += word in HUNGARIAN
            word = ''
    if any(char in low for char in 'őű'):
        hun += 2
    indo, hung = ind > .6, hun > .6
    inside = bool(oldword and low and low[0].isalpha())
    value = -.002
    if 'ny' in text and text.strip().isalpha():
        suffix = text.endswith('nya')
        strength = 3 / max(3, len(text)) if suffix else 1
        if inside:
            value -= 2.2 * strength if suffix else .13
            value -= strength * (2.2 * indo + 1.2 * hung)
        elif text.strip() in ('ny', 'nya') or indo or hung:
            value -= .3 + 1.2 * indo + 1.1 * hung
    if inside and oldword.endswith('ny'):
        value -= .13 + 4.1 * indo + 1.2 * hung
    if inside and previous.endswith('n'):
        if text.startswith('y'):
            value -= .2 + 4.1 * indo + 2 * hung
            if (2 <= len(text) <= 3 and text[1] in 'aeiou'
                    and text[-1] not in 'ngl'):
                value -= 4.9
        elif not text.startswith('n') and 'ny' not in text:
            if previous.endswith('en') and len(previous.strip()) <= 4:
                value += -.035 + 1.3 * indo
                if previous.strip() in ('men', 'pen'):
                    value += .46
    if oldword == 'many':
        if low in (' a', ' an'):
            value -= 5.1
        elif low == ' as':
            value -= 1.6
    if position == 0 and text.strip() in ('any', 'many'):
        value -= 2
    if position == 1 and previous == 'title' and low == ':':
        value = -4.9
    return (doc, s, word, ind, hun, position + 1), value

"""A document-opening pulse, plus weaker layout and filesystem-path signals.

The negative opening pulse continues through repetitions of the opening token.
Its size is estimated from writing system, case, length, word frequency,
programming keywords and suffixes, rather than a vocabulary lookup. There is
also a smaller negative pulse on indentation, fading as indented lines accumulate.
Conventional directory names after slashes and TeX environment braces have
positive signals; null bytes have a negative signal. Other positions predict zero.
"""
import unicodedata
import keyword
import regex
from wordfreq import zipf_frequency

READS = ()

# Declaration and control-flow words across common programming languages.
CODE_WORDS = frozenset(keyword.kwlist) | frozenset('''
public private protected static const var let void int bool string using
namespace include function package export interface struct typedef enum
extends implements
'''.split())

# Conventional Unix/macOS directories and the workspace used by coding tools.
DIRECTORIES = frozenset('''
bin boot dev etc home lib lib64 media mnt opt proc root run sbin srv sys tmp
usr var Users Volumes Applications workspace local
'''.split())


def opening(text):
    word = text.strip()
    if text == '<|im_start|>':
        return -5.22
    if text == '<|endoftext|>':
        return -17.65
    if text == '<|im_end|>':
        return -4.31
    if not word:
        if '\t' in text:
            return -15.58 if text == '\t' else -11.0
        if '\xa0' in text:
            return -13.5
        if '\n' in text:
            return -12.84 if text == '\n' else -7.1
        return -7.24 if text == ' ' else -9.0
    if len(word) > 1 and set(word) == {'·'}:
        return -20.75
    if word.isdigit():
        return -8.8
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        value = -6.1 if len(word) == 1 else -7.2
        if unicodedata.category(word[0]) in {'Sm', 'Pd'}:
            value += 1.6
        if text.endswith('\n'):
            value -= 1.2
        return value
    if regex.search(r'\p{Script=Han}', word):
        return -7.4
    if regex.search(r'\p{Script=Cyrillic}', word):
        return -9.6
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return -7.2
        length = min(len(word), 10)
        leading_space = text.startswith(' ')
        title = word.istitle()
        value = -7.8 - 0.15 * length
        if leading_space:
            value += 0.3 - 0.2 * length
        elif word.islower():
            value -= 1.25
        if title:
            value += 0.9
        if word.isupper():
            value -= 0.6
        if zipf_frequency(word, 'en') >= 6:
            value += 1.9 + 0.5 * title
        if not leading_space and word.lower() in CODE_WORDS:
            value += 3.5
        if word.lower().endswith('ing'):
            value += 1.5
        if word.lower().endswith('ed'):
            value -= 0.5
        return value
    return -9.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, initial, recent, indents = prefix.token_ids[-1], True, '', 0
    else:
        _, first, initial, recent, indents = carry
        initial = initial and prefix.token_ids[-1] == first

    indentation = bool(text) and set(text) <= {' ', '\t'} and recent.endswith('\n')
    value = 0.0
    if initial:
        value = opening(text)
    elif indentation:
        value = -1.05 / (1 + 2 * indents)
    elif text == '\x00':
        value = -1.7
    elif text == '{' and (recent.endswith('\\begin') or recent.endswith('\\end')):
        value = 1.3
    else:
        directory = text.lstrip('/')
        if directory in DIRECTORIES:
            if text.startswith('/'):
                value = 0.5
            elif recent.endswith('/'):
                value = 1.8 if directory == 'workspace' else 1.4
    if indentation:
        indents += 1
    return (doc, first, initial, (recent + text)[-32:], indents), float(value)

programs.haiku:
"""Cross-reference pointer detector.

Fires on the word that opens a pointer to another place or source, mostly in academic,
patent and legal writing. Its strongest triggers:
  * "see" used as a pointer ("..., see Col. 3", "please see the ...", "See also", not the
    verb "I see"), and "also" right after "see" ("see also United States v ...");
  * "in" after a verb of showing or describing, which points at where the thing is
    ("as shown [in] FIG. 2", "as described [in] section 3", "defined [in] the Act");
    the weaker the verb, the weaker the pointer ("used in" and "found in" are small);
  * citation abbreviations that introduce a source: "cf.", "vgl.", "Cfr.", "Voir",
    "Siehe", "e.g." (the letters and the period that closes them), and "(quoting" / "(citing".
Everywhere else it is near zero.
"""
import re

READS = ()

STRONG = ("described", "discussed", "disclosed", "defined", "specified", "shown",
          "illustrated", "indicated", "set forth", "set out", "listed", "summarized")
MEDIUM = ("mentioned", "given", "proposed", "presented", "depicted", "provided", "recorded")
STRONG_RE = re.compile(r"\b(" + "|".join(STRONG) + r")( \w+)? (in|under)$")
MEDIUM_RE = re.compile(r"\b(" + "|".join(MEDIUM) + r")( \w+)? (in|under)$")
PARTICIPLE_RE = re.compile(r"\b\w+ed (in|under|from)$")
CITE_RE = re.compile(r"(vgl|Vgl|cf|Cf|Cfr|cfr|Voir|voir|Siehe|siehe)\.?$")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        before = ""
    else:
        before = carry
    full = (before + tok)[-40:]
    word = tok.strip()
    value = 0.0
    if word in ("see", "See"):
        pre = before.rstrip()
        if pre.endswith(("please", "Please")):
            value = 8.0
        elif pre == "" or not pre[-1].isalpha():
            value = 6.0  # a pointer: punctuation or line start before it, not "I see"
        else:
            value = 0.5
    elif word == "also" and re.search(r"\b[Ss]ee\s*$", before):
        value = 8.0
    elif word == "refer" and re.search(r"\b[Pp]lease\s*$", before):
        value = 5.0
    elif word in ("gl", "fr", "cf", "Cf", "Cfr", "cfr", "oir", "he", ".") and CITE_RE.search(full):
        value = 5.0
    elif word in ("g", ".g") and re.search(r"\b[Ss]ee,? e$", before):
        value = 5.0
    elif word.startswith(".") and before.endswith("e.g"):
        value = 5.0 if re.search(r"\b[Ss]ee,? e\.g$", before) else 1.0
    elif word in ("oting", "iting") and re.search(r"\((qu|c)$", before):
        value = 4.0
    elif word in ("in", "under") and STRONG_RE.search(full):
        value = 6.0
    elif word in ("in", "under") and MEDIUM_RE.search(full):
        value = 3.0
    elif word in ("in", "under", "from") and PARTICIPLE_RE.search(full):
        value = 0.5
    return full, value

programs.sol:
"""An Italian-context-sensitive spelling response.

Recent word frequencies, together with an Italian grammatical-word cue,
estimate whether the text is Italian. In that context, short z-bearing
pieces are positive, clipped c/d pieces are negative, and several common
Italian function words and word-initial fragments have separate responses.
Romanian t-with-comma/cedilla has a small independent positive response.
This approximation leaves out many less systematic lexical responses.
"""
from functools import lru_cache
import unicodedata
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = (
    'it', 'en', 'es', 'fr', 'pt', 'de', 'ro', 'pl', 'tr', 'cs', 'hu',
)
ITALIAN_GRAMMAR = frozenset('''
    di il gli della dello delle degli nel nella nelle nello negli
    alla alle allo agli sul sulla sulle sono che perché più
    questo questa questi queste anche essere senza
'''.split())

# Signed responses to short Italian grammatical words and verb stems.
GRAMMATICAL_PIECES = {
    'da': 3.2,
    'ad': -2.1,
    'ed': -2.1,
    'si': -2.0,
    'se': 1.2,
    'do': 1.7,
    'dov': 2.2,
    'fa': -2.0,
    'fe': 2.5,
}
WORD_STARTS = {
    'con': 0.8,
    'cont': 3.2,
    'sp': 2.1,
    'str': 2.1,
    'av': 1.2,
}


@lru_cache(maxsize=65536)
def word_evidence(word):
    if not word.isascii() and any(
        not unicodedata.name(c, '').startswith('LATIN') for c in word
    ):
        return None
    frequencies = [zipf_frequency(word, lang) for lang in LANGUAGES]
    best = max(frequencies)
    if best < 2.5:
        return None
    return tuple(max(-3.0, f - best) for f in frequencies)


def update_language(scores, word):
    evidence = word_evidence(word.lower())
    if evidence is None:
        return scores
    updated = [0.7 * s + e for s, e in zip(scores, evidence)]
    best = max(updated)
    return tuple(s - best for s in updated)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc or token == '<|endoftext|>':
        carry = (doc, '', (0.0,) * len(LANGUAGES), 0)
    _, word, scores, cue_lifetime = carry
    previous_word = word

    for character in token:
        if character.isalpha():
            word = (word + character)[-40:]
        elif word:
            scores = update_language(scores, word)
            if word.lower() in ITALIAN_GRAMMAR:
                cue_lifetime = 20
            else:
                cue_lifetime = max(0, cue_lifetime - 1)
            word = ''

    provisional = update_language(scores, word) if len(word) >= 2 else scores
    margin = provisional[0] - max(provisional[1:])
    italian = max(0.0, min(1.0, margin / 1.5))
    if cue_lifetime == 0 and word.lower() not in ITALIAN_GRAMMAR:
        italian = 0.0

    piece = token.strip().lower()
    value = GRAMMATICAL_PIECES.get(piece, 0.0)
    if token[:1].isspace() or token[:1].isupper():
        value += WORD_STARTS.get(piece, 0.0)

    if piece.isalpha() and len(piece) <= 6:
        if 'z' in piece:
            value += 0.5
        if piece.isascii() and piece.endswith('z'):
            if piece == 'z':
