import re
import unicodedata

READS = ()

# Corresponding letters in Cyrillic, Greek and Arabic spellings of mat.
LETTERS = str.maketrans({'м': 'm', 'а': 'a', 'т': 't',
                         'μ': 'm', 'α': 'a', 'τ': 't',
                         'م': 'm', 'ا': 'a', 'ت': 't'})


def plain(text):
    text = unicodedata.normalize('NFD', text.lower())
    letters = ''.join(c for c in text if not unicodedata.combining(c))
    return letters.translate(LETTERS)


def response(token, tail, recent):
    s = plain(token)
    joined = tail + s
    cut = len(tail)
    spaced = bool(token[:1].isspace())
    # Math library names: a much larger response in imports and C includes.
    if re.fullmatch(r'[^\w]*c?maths?', s):
        if s == 'cmath':
            return 3.0
        if re.search(r'\b(?:import|from)\s*$', recent) or recent.endswith('<'):
            return 9.7
        if recent.endswith('\\'):
            return -0.2
        if s.startswith('.'):
            return 10.7
        if re.search(r'[\[(=,:`]\s*$', recent) or s.startswith('('):
            return 1.9
        if s.startswith(('/', '_')) or s == 'cmath':
            return 3.0
        return 0.6 if spaced else 1.3
    if 'mathemat' in s:
        return -0.3 if 'ical' in s else -1.1
    # Only a newly completed syllable counts, not one in an earlier token.
    hits = [m for m in re.finditer('mat', joined) if m.end() > cut]
    if hits:
        at = hits[-1].start()
        rest = joined[at:]
        if rest.startswith('math'):
            if rest in ('math', 'maths'):
                return 1.3
            return -1.1 if rest.startswith('mathemat') else -0.002
        # Common whole words whose mat is not the productive matic syllable.
        if rest.startswith(('match', 'matt', 'mater', 'matur', 'mation', 'matr')):
            return -0.002
        if s.strip() in ('format', 'formats'):
            return -0.002
        if spaced:
            if s.rstrip().endswith('mat') and s.strip() != 'mat':
                return -2.4
            if 'systematic' in s:
                return -5.8
            if 'automatic' in s:
                return -2.1 if s.endswith('ally') else -3.4
            if s.strip() in ('mat', 'mats'):
                return -2.2
            if 'matic' in s or s.rstrip().endswith('mat'):
                return -0.7
            return -0.2
        if at < cut:
            ordinary = ('matь', 'matся', 'mator', 'maton')
            if rest.startswith(ordinary) or rest == 'mato':
                return -0.002
            if rest.startswith('matically'):
                return -1.9
            if tail.endswith('system'):
                return -9.0
            if tail.endswith(('clim', 'estim', 'diplom')):
                return -2.4
            if rest.startswith(('mate', 'mating', 'matin')):
                return -2.4
            return -3.9
        if s.startswith('mat'):
            if len(s) > 3 and not s.startswith(('matic', 'matis', 'matiz')):
                return -1.9 if s == 'mate' else -0.002
            return -4.1 if token.isupper() else -4.9
