    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, recent = '', ''
    else:
        _, tail, recent = carry
    token = prefix.token_strings[-1]
    value = response(token, tail, recent)
    text = plain(tail + token)
    match = re.search(r'[^\W\d_]+$', text)
    tail = match.group()[-24:] if match else ''
    recent = (recent + token.lower())[-48:]
    return (doc, tail, recent), value

