import re

READS = ()

# Different familiar opening layouts have different pulse sizes.
OPENING_LAYOUT = {
    '<|endoftext|>': 6.84,
    '\n': 2.12,
    '\n\n': 1.57,
    '\r': -0.99,
    '\xa0': 1.9,
    r'\t': 5.58,
    '/*': 6.1,
    '/*\n': 10.25,
    '/*\r\n': 8.7,
    '"""\n': 7.8,
    "'''\n": 4.2,
    '**': 4.56,
    '```': 2.0,
    '··': 1.84,
}


def opening_value(s):
    if s in OPENING_LAYOUT:
        return OPENING_LAYOUT[s]
    if s and set(s) == {'\t'}:
        return 6.8 / len(s)
    if s.startswith('/*'):
        return 2.0
    if s.startswith('#!'):
        return 1.9
    if re.fullmatch(r'\\x[0-9a-fA-F]{1,2}', s):
        return 2.4
    if s == 'I':
        return 5.5
    if len(s) == 1 and s.isascii() and s.isalpha():
        return 0.7
    if '\n' in s and not any(c.isalnum() for c in s):
        return 1.1
    if s and set(s) == {' '}:
        return 0.36 if len(s) == 1 else (0.14 if len(s) == 2 else -0.3)
    if '\\' in s and not any(c.isalnum() for c in s):
        return 2.5
    if s.lstrip().startswith(('"', "'", '“', '‘')):
        return 1.4
    if s.startswith(' ') and s.strip() == '-':
        return 2.1
    if not any(c.isalnum() for c in s):
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first = 0, s
        layout_run = s.isspace() or s == '··'
    else:
        _, position, first, layout_run = carry
        layout_run = layout_run and s == first
    if position == 0 or layout_run:
        value = opening_value(s)
    elif position == 1 and first == 'Title' and s == ':':
        value = 15.4
    else:
        value = 0.0
    return (doc, position + 1, first, layout_run), value

programs.haiku:
"""Component layers.1.mlp.down_proj:2420: a document-opener detector.

What it does: the component is nearly silent inside a document. Its strong activity is on
the first token of each document (the token right after <|endoftext|>, or the first token
of a packed row), where the attention has no earlier text to look at. There its activation
depends on what kind of token opens the document:

  - a block-comment or docstring opener ("/*", "/**", triple quotes) is strongly positive;
  - a tab or an escaped tab is strongly positive (a double tab is less so);
  - the pronoun "I" is strongly positive (but " I", with a space, is not);
  - a newline (or escaped newline) is clearly positive;
  - a quote character is positive;
  - a bracket or brace is weakly positive, a single capital letter mildly positive;
  - a "#" or other punctuation, and ordinary words (capitalised, lowercase, CJK), are near
    zero; digits are slightly negative.
If the second token of a document just repeats the first, it gets the same value.

One rare but very strong case: in a document that opens with the word "Title", the colon
right after it is very strongly positive.

Everything else predicts 0. The values are rounded means measured on about 14k training
rows; the sign and rough size of each class is the explanation, not an exact table.
"""

READS = ()

BLOCK_OPENERS = ("/*", '"""', "'''")
NEWLINE_TOKENS = ("\n", "\r\n", "\\n", "\n\n", "\r", ".\n", ":\n", ",\n")
QUOTES = ('"', '\\"', "“", '"I')
BRACKETS = ("{", "[", "(", " {", " (", "{\n", "[\n")


def opener_value(token):
    """Predicted activation for a token that is the first token of a document."""
    if token == "<|endoftext|>":
        return 6.8
    if token == "I":
        return 5.5
    if token.startswith(BLOCK_OPENERS):
        return 7.0
    if token == "\t" or token == "\\t":
        return 6.0
    if token in ("\t\t", "\t\n", "\t\t\t"):
        return 3.0
    if token in NEWLINE_TOKENS:
        return 1.9
    if token in QUOTES:
        return 2.2
    if token in BRACKETS:
        return 0.8
    if token == "#":
        return 0.4
    if len(token) == 1 and token.isalpha():
        return 1.2 if token.isupper() else 0.5
    if token[:1].isdigit():
        return -0.05
    if token[:1] in "\t\n\r" or not token[:1].isalnum() and token[:1].isascii():
        return 0.2
    return 0.05


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    toks = prefix.token_strings
    opens_doc = t == 0 or docs[t] != docs[t - 1]
    if opens_doc:
        return carry, opener_value(toks[t])
    second = t >= 1 and (t == 1 or docs[t - 1] != docs[t - 2])
    if second and toks[t] == toks[t - 1]:
        return carry, opener_value(toks[t - 1])
    if second and toks[t - 1] == "Title" and toks[t] == ":":
        return carry, 15.4
    return carry, 0.0

