# Intercept and log-length slope for a delimiter attached to a word.
BOUND_WORD = {
    '/': (-0.57, -0.56),
    '.': (-0.54, -0.20),
    '-': (-0.61, -0.10),
    '_': (0.04, -0.27),
    '(': (-0.38, -0.20),
    ',': (-0.39, -0.50),
    '[': (-0.38, -0.31),
    '<': (-0.73, -0.30),
    ':': (-1.09, -0.26),
    '=': (-0.64, -0.21),
    '*': (-0.67, -0.23),
    '+': (-0.62, -0.08),
    '@': (-1.02, -0.08),
    '#': (-0.54, -0.14),
    ';': (-0.41, -0.29),
    '$': (-0.37, -0.11),
    '\t': (-0.04, -0.36),
}
CONTRACTIONS = {'s', 't', 're', 've', 'll', 'd', 'm'}
LEGACY_DOMAINS = {'com', 'org', 'net', 'edu', 'gov', 'mil', 'int'}
SOURCE_EXTENSIONS = {
    'py', 'go', 'rs', 'ts', 'tsx', 'js', 'jsx',
    'java', 'cpp', 'h', 'c', 'rb', 'sh',
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    initial = (prefix.position == 0 or
               prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if initial else prefix.token_strings[-2]
    value = 0.
    if s == '<think>':
        value = .89
    elif s.startswith('<|') and s.endswith('|>'):
        value = -.52 if initial else -.04
    elif re.fullmatch(r'</?\w+>', s):
        value = -.06
    elif len(s) > 1 and s[1].isalpha() and (
            not s[0].isalnum() and s[0] != ' '):
        c, word = s[0], s[1:]
        length = math.log2(len(s))
        if c in "'’":
            value = -.03 if word.lower() in CONTRACTIONS else -.8
        elif c == '\\' and word in {'n', 't', 'r', 'b', 'f', 'v'}:
            value = -.08
        elif c == '\\' and word.startswith('x'):
            value = -.35 - .15 * (len(word) - 1)
        else:
            base, slope = BOUND_WORD.get(c, (-0.12, -0.40))
            value = base + slope * length
            if word[0].isupper():
                value -= .11 + (.14 if c == '_' else 0.)
            if c == '.':
                if word in LEGACY_DOMAINS:
                    value -= 1.05
                elif word in SOURCE_EXTENSIONS:
                    value += 0.26
            if c in '/._-' and previous and previous[-1].isspace():
                value -= 1.27
            if initial:
                value = 2.
    elif len(s) > 1 and s[0] in '的了':
        value = -.95 if s[0] == '的' else -.8
    elif regex.match(r'^[のをにとがでへはも]\p{Script=Han}', s):
        value = -1.
    elif (len(s) > 1 and s[0] in '.:,=/' and s[1] != s[0]
          and not s[1].isalnum() and not s[1].isspace()
          and s[1] != '\\'
          and not s.startswith(('://', '/*'))):
        value = -.25
    elif initial:
        if s.startswith(' '):
            value = .44
        elif s and s[0].isascii() and s[0].isalpha():
            value = .03 + .53 * math.log2(1 + len(s))
            value -= .46 * s[0].isupper() + .13 * s.isupper()
        elif s and not s[0].isalnum() and not s.isspace():
            value = .17 if len(s) == 1 else 1.
    elif s and s[0].isalpha() and previous.endswith(('/', '.')):
