from collections import deque
from functools import lru_cache
import unicodedata

READS = ()
GROUPS = {
    'search': {'find'},
    'determine': {'determine'},
    'calculate': set('calculate compute count'.split()),
    'get': set('get take'.split()),
    'obtain': set(('obtain retrieve fetch extract derive recover '
                   'access collect gather').split()),
    'return': {'return'},
    'output': set('print println display output log'.split()),
    'tell': set(('give provide show tell state report indicate reveal '
                 'produce yield write list generate').split()),
    'evaluate': set(('evaluate assess estimate measure predict identify '
