ROOTS = {word: group for group, words in GROUPS.items() for word in words}
OBJECTS = set('the its their our your his her'.split())
MATH = set(('equation polynomial triangle integer coefficient minimum '
            'maximum sum mean angle distance area volume probability ratio '
            'fraction square derivative integral limit factor divisor vector '
            'matrix perimeter radius rectangle quadratic solve solution '
            'tangent coordinates width height length circle gcd lcm modulus '
            'expression sine cosine slope').split())
