# imperative. The object column is separate because it applies one word later.
PROFILE = {
    'search': (.76, -1.55, -1.21, -1.75, 0, -.86, -1.16),
    'determine': (0, 0, -1.64, -1.01, 0, 0, 0),
    'calculate': (-.54, -.35, 0, -1.75, .54, .44, -.65),
    'return': (-.34, 0, -1.23, 0, -.42, 0, 0),
    'output': (-.17, -.18, 0, 0, 0, 0, 0),
}
OBJECT_AFTER = {
    'get': -.81, 'determine': -1.94, 'search': -3.33,
    'return': -2.41, 'obtain': -1.23, 'want': -.86,
    'calculate': -2.22,
}

@lru_cache(maxsize=16384)
def verb(word):
    """Recognize ordinary inflections of the named result-related verbs."""
    if word in ROOTS:
        return ROOTS[word], 'base'
    if word.endswith('s'):
        for root in (word[:-1], word[:-2], word[:-3] + 'y'):
            if root in ROOTS:
                return ROOTS[root], 'finite'
    for suffix, form in (('ing', 'gerund'), ('ed', 'past')):
        if word.endswith(suffix):
            stem = word[:-len(suffix)]
            undoubled = stem
            if len(stem) > 1 and stem[-1] == stem[-2]:
                undoubled = stem[:-1]
            for root in (stem, stem + 'e', undoubled):
                if root in ROOTS:
                    return ROOTS[root], form
