        (.76, word == 'of' and prev == 'number'),
        (.75, word == 'all' and prev in {
            'of', 'over', 'among', 'through', 'between'}),
        (1.47, word == 'all' and bool(verb(prev)[0])),
        (.47, word == 'what' and (
            current.strip()[:1].isupper() or initial)),
        (1.10, word in {'is', 'are', 'was', 'were', "'s", '’s'}
         and prev == 'what'),
        (.84, word in {'many', 'much'} and prev == 'how'),
        (2.28, word == 'out' and prev in {
            'find', 'figure', 'figuring', 'work', 'working'}),
        (1.98, word == 'for' and prev in {'ask', 'asked', 'asking', 'asks'}),
        (.59, word == 'for' and prev in {
            'look', 'looking', 'search', 'searching'}),
        (1.00, word == 'in' and prev == 'interested'),
        (.20, word == 'to' and prev in {
            'need', 'needs', 'want', 'wants', 'have', 'has', 'is', 'was'}),
