def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        history, math_count, goal_count, only_cr = deque(), 0, 0, True
    else:
        _, history, math_count, goal_count, only_cr = carry
    math, goal = math_count > 0, goal_count > 0
    raw = prefix.token_strings[-1]
    flags = context_flags(raw)
    history.append(flags)
    math_count += flags[0]
    goal_count += flags[1]
    if len(history) > 40:
        goal_count -= history[-41][1]
    if len(history) > 128:
        math_count -= history.popleft()[0]
    only_cr = only_cr and raw == '\r'
    carry = doc, history, math_count, goal_count, only_cr

    # Fixed-size lookback; never joins text across a document boundary.
    strings = [prefix.token_strings[-1 - k]
               if k <= prefix.position and prefix.document_ids[-1 - k] == doc
               else '' for k in range(4)]
