        combined = prev + current
        if verb(combined.strip().lower())[0]:
            current, prev, before = combined, before, third
    value = phrase_value(current, prev.strip(), before.strip(), third.strip(),
                         initial, math, goal)
    if only_cr:
        value = 6.82
    if initial and raw == '//\n':
        value = 9.72
    return carry, float(value)

programs.haiku:
"""Layer 1, MLP down_proj, component 2423: a 'a quantity is being asked for' detector.

It is negative (the component's typical big values) on the words that open a request to
compute something in a problem or a coding task:
  - the verbs find / calculate / compute / count when they are an instruction or a goal
    ("we need to find", "to compute", "Find the ...", "Calculate ..."), strongest after
    goal words such as need / want / have / asked / how to;
  - the verbs determine / retrieve / obtain and return / returns (weaker);
  - the word "the" right after such a verb ("find the", "returns the", "to determine the"),
    and "the" in "what is the ...";
  - weaker cues: "then the", "what is", "how many", "number of".
A declarative use after a subject or modal ("I find that", "I will find", "would not find") is
near zero or slightly positive, as is a finished result ("determined", "identified").
Everything else is 0. Predictions are in the component's own units (activation scale)."""
READS = ()

STRONG = {"find", "calculate", "compute", "count", "calculating", "computing", "counting"}
MEDIUM = {"determine", "retrieve", "obtain", "determining"}
RETURN = {"return", "returns"}
SUBJECT = {"i", "will", "would", "may", "might", "not", "cannot", "also", "'ll", "can't", "(", "in"}
GOAL = {"need", "needs", "want", "wants", "have", "has", "is", "asked", "asks", "how",
        "trying", "going", "must", "should", "tasked", "order", "us"}
WHAT = {"is", "are", "'s"}
DISCOVERED = {"determined", "identified", "determination", "determines", "findings", "discover",
              "identifies", "noticed"}


def step(carry, prefix, upstream):
    """carry = the two previous words (lowercased), reset at each document start."""
    word = prefix.token_strings[-1].strip().lower()
    prev, prev2 = carry if carry is not None else ("", "")
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev, prev2 = "", ""

    value = 0.0
    if word in STRONG:
        if prev == "to" and prev2 in GOAL:
            value = -4.0          # "need to find", "asked to compute"
        elif prev in SUBJECT:
            value = 0.3           # "I find that", "I will find" (a statement, not a request)
        else:
            value = -1.1          # "Find the ...", "to calculate", ", find ..."
    elif word in MEDIUM and prev not in SUBJECT:
        value = -0.6
    elif word in RETURN and prev not in SUBJECT:
        value = -0.5
    elif word == "the" and prev in STRONG:
        value = -4.0              # "find the", "calculate the"
    elif word == "the" and (prev in MEDIUM or prev in RETURN):
        value = -2.9              # "determine the", "returns the"
    elif word == "the" and prev in {"then", "thus", "so"}:
        value = -0.8              # "then the" in a derivation
    elif word == "the" and prev in WHAT and prev2 == "what":
        value = -3.1              # "what is the"
    elif prev == "what" and word in WHAT:
        value = -1.2
    elif prev == "how" and word == "many":
        value = -1.2
    elif prev == "number" and word == "of":
        value = -0.7
    elif word in DISCOVERED:
        value = 0.6
    return (word, prev), value

programs.sol:
"""Mathematical equality, plus the first indentation of a document.

Equality and approximate-equality notation have a negative response.  An
indented-code context or member access weakens it; a multi-letter identifier
also looks more like an assignment than a mathematical variable.  A newly
encountered line indentation gives a separate negative pulse, which rapidly
fades as indentation repeats.  Everything else is left at zero.
"""
import re

READS = ()
INDENT = re.compile(r'\n[ \t]{2,}\S')
MEMBER = re.compile(r'\.[A-Za-z_]')
RELATIONS = ('≈', '≃', '≅', '≡', '≊', '≍', '≒', '∼')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, indents = '', '', 0
    else:
        _, recent, previous, indents = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    p = previous.strip()
    one_letter = len(p) == 1 and p.isalpha()
    closed = bool(p) and p[-1] in ')}]²³'
    value = 0.0
    if s in ('=', ')=', '}=', ']=', '=\\', '=-', '=('):
        if INDENT.search(recent):
            value = -0.11 if closed else -0.01
        elif MEMBER.search(recent):
            value = -0.13 if one_letter else -0.035
        elif ';' in recent:
            value = -0.11
        elif len(p) > 1 and p.isalpha():
            value = -0.27 if p.isupper() else -0.12
        else:
            value = -0.34
    else:
        # Rejoin bytes so a split Unicode relation is recognized on completion.
        ending = b''.join(prefix.token_bytes[-3:]).decode('utf8', 'ignore')
        latex = previous.rstrip().endswith('\\') and s in (
            'sim', 'approx', 'simeq', 'equiv', 'cong'
        )
        if ending.endswith(RELATIONS) or latex:
            value = -0.43
        elif s == '~' and (one_letter or closed):
            value = -0.28
        elif len(token) >= 2 and not token.strip(' \t'):
            if previous.endswith('\n'):
                value = -0.45 * (0.2 ** min(indents, 5))
                indents += 1
    return (doc, (recent + token)[-160:], token, indents), value

programs.haiku:
"""Clause openers of condition or time: a negative response on the opening word.

The component goes strongly negative on the word that opens an adverbial clause saying
when, on what condition, or until when something holds: "unless", "once", "until",
"provided (that)", "as long as", "as soon as", "in case", "in the event", "by the time",
"upon", "whenever", and the same words in German, Spanish, Chinese and others.
Weaker responses come from "when", "as", "after", "before" and "if" in running English.
Ordinary uses stay near zero: "served as", "such as", "known as", "as well as",
"during", "since", "because", "and", "but", and "if" opening a line of code.
At the first token of a document it is weakly positive (about +0.2).

The program reads each word as it arrives, without looking ahead, and uses the one or
two words before it for context. It is a hand-written table, not a fitted model.
"""

READS = ()

# Typical activation of a word that opens a clause of condition or time, by lowercase word.
OPENERS = {
    "unless": -1.9, "once": -1.5, "until": -1.1, "till": -0.9, "til": -0.9,
    "provided": -0.9, "before": -0.5, "after": -0.5, "upon": -0.7, "otherwise": -0.8,
    "whenever": -0.8, "assuming": -0.6, "when": -0.6, "while": -0.3, "if": -0.25,
    "as": -0.4, "throughout": -0.6, "based": -0.4, "depending": -0.3, "moment": -0.5,
    "bis": -2.0, "bevor": -1.8, "待": -1.9, "只要": -2.4, "若": -1.0, "如": -0.9,
    "caso": -1.0, "falls": -1.3, "ere": -1.5,
}
# Sentence-initial capitalised forms that differ from the lowercase ones.
CAPITALISED = {"When": -0.2, "If": 0.0, "After": -0.2, "Before": -0.25, "As": -0.6}
# Words after which "as" is a role or comparison, not the start of a clause.
PLAIN_AS_AFTER = {"such", "well", "known", "served", "defined", "same", "used", "written",
                  "be", "identified", "serves", "serve", "treated", "expressed", "is", "are"}
# Words after which "if" or "when" is a plain conjunction, weak or absent.
WEAK_AFTER = {"", ",", "and", "but", "so", "that", "see", "know", "else", ":"}
DOCUMENT_START = 0.2


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    t = prefix.position
    if t == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, DOCUMENT_START
    # Previous two words of the same document, stripped; "" means a line break or indent.
    prev = prefix.token_strings[-2].strip().lower()
    prev2 = prefix.token_strings[-3].strip().lower() if t > 1 else ""
    if word in CAPITALISED:
        value = CAPITALISED[word]
    else:
        value = OPENERS.get(lower, 0.0)
    if lower == "as":
        if prev in ("long", "soon"):
            value = -4.0
        elif prev in PLAIN_AS_AFTER:
            value = 0.0
        elif prev == ",":
            value = -0.6
    elif lower == "if":
        if prev in WEAK_AFTER:
            value = 0.0
        elif prev in ("only", "again", "even"):
            value = -1.0
    elif lower == "when" and prev in WEAK_AFTER:
        value = -0.2
    elif lower == "case" and prev == "in":
        value = -4.5
    elif lower == "event" and prev == "the" and prev2 == "in":
        value = -2.0
    elif lower == "time" and prev in ("the", "next", "any", "each"):
        value = -0.8
    return carry, float(value)

programs.sol:
"""Approximate a mixed lexical feature, leaving most positions at zero.

Negative cues are loan spellings, Chinese male/female terms, payments, and
prizes.  Compounds are weaker; certain award/payment contexts are stronger.
A streaming decoder also recognizes Chinese characters split across tokens.
The BE byte is positive especially when completing Japanese 対 or an unfinished
character.  Repeated middle dots and a document-opening `package` keyword
have their own responses.  This does not model the remaining context variation.
"""
import codecs
import re

READS = ()


def response(text, raw, previous, split, first):
    word = text.strip()
    lower = word.lower()
    if lower in ('loan', 'loans'):
        if word[0].isupper():
            return -4.0
        return -3.5 if text.startswith(' ') else -1.5
    # A split 'loan', including the capital-I/lowercase-l lookalike.
    if lower in ('an', 'ans'):
        preceding = re.search(r'[A-Za-z]+$', previous)
        if preceding and preceding[0] in ('lo', 'Lo', 'LO', 'Io'):
            return -5.0

    # Male/female characters and common gendered descriptions.
    if word in ('男', '女'):
        if word == '女' and previous.endswith('彼'):
            return -0.8
        value = -4.0 if word == '男' else -2.7
        return value * (1.8 if split else 1.0)
    if word == '男女':
        return -2.7
    if word.startswith(('男', '女')):
        male = word.startswith('男')
        rest = word[1:]
        if rest in ('子', '生'):
            return -3.0 if male else -2.1
        if rest == '主角':
            return -2.5 if male else -1.7
        if rest == '孩':
            return -0.9 if male else -1.9
        if rest in ('人', '士'):
            return -1.15
        if rest in ('性', '孩子', 'の子'):
            return -0.65
        return -0.35
    if word.endswith(('男', '女')):
        return -0.4

    # Money lent, payment amounts, and prizes.  Do not treat every monetary
    # expression alike: these are responses to the written Chinese words.
    if word in ('奖', '獎', '奨'):
        award_name = previous.endswith(('贡献', '大会', '进步', '金像', '奥斯卡'))
        value = -6.5 if award_name else -4.5
        return value * (1.65 if split else 1.0)
    if word in ('贷', '貸'):
        return -4.0 * (1.5 if split else 1.0)
    if word == '款':
        if previous.endswith(('货', '貨')):
            return -6.5
        return -4.5 if split else -2.2
    if word == '贷款':
        return -4.0
    if word in ('借款', '貸款'):
        return -2.7
    if word.startswith(('奖', '獎')):
        return -1.3
    if word.endswith('款'):
        return -0.6

    if raw == b'\xbe':
        return 1.9 if word in ('', '対') else 0.2
    if len(word) > 1 and set(word) == {'·'}:
        return -1.22
    if first and word == 'package':
        return 1.01
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        previous = ''
        first = True
    else:
        _, decoder, previous = carry
        first = False
    raw = prefix.token_bytes[-1]
    split = bool(decoder.getstate()[0])
    text = decoder.decode(raw)
    value = response(text, raw, previous, split, first)
    return (doc, decoder, (previous + text)[-12:]), value

"""A BOTH-centered lexical signal, not a general quantifier classifier.

BOTH is strongest after multiplication/division verbs and linking words,
weaker after prepositions or some auxiliaries. ALL and selected translations also
respond. Short bot/oth-like pieces and word-internal b+o completions model
some spelling-based responses, including Latin/Cyrillic transliterations.
Everything else receives a near-zero baseline. Document boundaries reset
our short text history.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()
PREPOSITIONS = set(
    'of for in on to by at with as from through over between'.split()
)
AUXILIARIES = set('is are was were be been being has have had'.split())
CONJUNCTIONS = set('and so when if while that since because'.split())
ALL_FORMS = set('alle allen alles todo todos toda todas tout tous toute toutes '
                'tutti tutte все всё جميع'.split())
BOTH_FORMS = set('beide beiden ambos ambas både båda оба обе обоих'.split())
# Common stop/fricative spellings, for short fragment completions.
OBSTRUENT_LETTERS = frozenset('ptkbdgcszfvjh')

@lru_cache(maxsize=100000)
def roman(s):
    return anyascii(s).lower()


def activation(s, previous, tail):
    w = s.strip().lstrip('_').casefold()
    prevword = re.search(r'([a-z]+)$', tail.lower())
    prevword = prevword.group(1) if prevword else ''
    if w == 'both':
        if prevword in {'multiply', 'multiplying', 'divide', 'dividing'}:
            return 9.91
        if prevword in PREPOSITIONS:
            return 4.13
        if prevword in {'is', 'was', 'has', 'be', 'been', 'being'}:
            return 2.86
        if prevword in AUXILIARIES:
            return 5.25
        if prevword in CONJUNCTIONS:
            return 7.39
        if s.strip() != s.strip().lower():
            return 6.31
        return 4.99
    if w == 'all':
        return 0.9 if s[:1].isspace() or s.strip()[:1].isupper() else 0.46
    if w in ALL_FORMS and (s[:1].isspace() or s.strip()[:1].isupper()):
        return 0.65
    if w in BOTH_FORMS:
        return 3.67
    # Continuations of the Spanish and Russian spellings of BOTH.
    if not s[:1].isspace():
        joined = (previous + s).strip().casefold()
        if joined in BOTH_FORMS and previous.strip().casefold() not in BOTH_FORMS:
            return 8.74
    # Only alphabetic spelling: don't treat Chinese pinyin as a word fragment.
    r = roman(s)
    p = roman(previous)
    internal = bool(regex.fullmatch(r'[\p{Latin}\p{Cyrillic}]+', s))
    alphabetic_previous = bool(regex.search(r'[\p{Latin}\p{Cyrillic}]$', previous))
    if internal and alphabetic_previous and p.endswith('b') and r.startswith('o'):
        if len(r) <= 3 and r.startswith('ot'):
            return 6.37
        if len(r) <= 3 and len(r) > 1 and r[1] in OBSTRUENT_LETTERS:
            return 2.73
        if len(r) <= 3 and r.startswith('om'):
            return 3.47
        return 0.67
    if internal and alphabetic_previous and p.endswith(('bo', 'bot', 'bos')):
        if r == 'oth' or (len(r) <= 2 and r[0] in OBSTRUENT_LETTERS):
            return 2.83
        return 0.41
    if r.strip() in {'bot', 'bots'}:
        return 3.98
    if r.strip() == 'oth' or (
        internal and alphabetic_previous and p.endswith('o')
        and r in {'th', 'ths'}
    ):
        return 2.58
    if r.strip() == 'booth':
        return 3.41
    if r.strip() == 'moth':
        return 1.92
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
        previous = ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, tail)
    return (doc, (tail+s)[-64:], s), value

programs.haiku:
"""'Both' detector, layers.1.mlp.down_proj:2428.

The component fires on the word "both" (English, and its translations in other languages), and
more weakly on "all" and its translations. Its activation is largest on the token that completes the
word, and it is still large when the word is split into subword pieces (e.g. "bo" + "th", "ob" + "е").
Otherwise it sits near zero: a few tenths of a unit of noise on ordinary text.

The program reads the word that ends at the current token (its trailing letters, read back through the
last few tokens of the same document) and predicts a fixed activation for each class of word.
"""

READS = ()

# "both", and its translations (German, Dutch, Spanish/Portuguese, Italian, Scandinavian, Czech, Polish, Russian)
BOTH = {
    "both", "beide", "beiden", "beider", "ambos", "ambas", "entrambi", "entrambe", "både", "begge",
    "oba", "obie", "obaj", "obě", "оба", "обе", "обоих", "обеих", "обоим", "обеим",
}
# "both" spelled out in pieces of the subword tokenizer
BOTH_PIECES = {"bot", "oth", "bots", "booth"}
# "all", and its translations: a weaker response
ALL = {"all", "todos", "todas", "tous", "toutes", "tutti", "alle", "toute", "todo"}

BOTH_VALUE = 5.1
PIECE_VALUE = 4.8
ALL_VALUE = 0.9


def trailing_word(prefix):
    """The letters ending at the current token, e.g. 'both' for ' both' or for 'bo' + 'th'."""
    text = ""
    last = prefix.document_ids[-1]
    for i in range(len(prefix.token_strings) - 1, max(-1, len(prefix.token_strings) - 5), -1):
        if prefix.document_ids[i] != last:
            break
        text = prefix.token_strings[i] + text
    word = ""
    for ch in reversed(text):
        if not ch.isalpha():
            break
        word = ch + word
    return word.lower()


def step(carry, prefix, upstream):
    word = trailing_word(prefix)
    if word.endswith("both") or word in BOTH:
        return None, BOTH_VALUE
    if word in BOTH_PIECES:
        return None, PIECE_VALUE
    if word in ALL:
        return None, ALL_VALUE
    return None, 0.0

