import re
import unicodedata

READS = ()
GERMAN = re.compile(
    r'\b(?:der|die|das|und|ist|nicht|eine|sich|den|dem|des|für|auch|ich|'
    r'sie|wir|ihr|aber|doch|noch|schon|werden|wird|kann|muss|weil|dass|hatte)\b'
