            value = 0.5  # TeX's \hat and \widehat accents
        elif GERMAN.search(context.lower()):
            value = 2.5 if raw.strip()[0].isupper() else 0.15
        else:
            value = 5.5 if word == 'hat' else 4.0
    elif word == '帽':  # Chinese word for a hat
        value = 4.5
    elif word == 'chat':
        value = 1.8 if raw == 'Chat' else 0.7
    elif word in ('hap', 'happ', 'chap'):
        value = -2.5
    elif s and s[0].isalpha() and not raw[0].isspace():
        # Do not generalize these short fragments to entire words such as
        # 'atmosphere' or grammatical endings such as '-ation'.
        if before.endswith('h'):
            if word == 'at':
                value = 6.0 if raw.lower() == s else 1.0
                if before.endswith('th'):
                    value = 1.8  # split spelling of 'that'
            elif word in ('att', 'ati', 'ata', 'atta'):
                value = 3.2
            elif word in ('anc', 'ance') and not before.endswith('enh'):
                value = -5.2 if word == 'anc' else -7.0
            elif word == 'app':
                value = -4.8
            elif word == 'az':
                value = -2.5
            elif word in ('ai', 'ut', 'ute'):
                value = 1.5
            elif word in ('ats', 'atty', 'atted'):
                value = 2.0
            elif word in ('ap', 'an', 'ans', 'ang'):
                value = -1.0
            elif word in ('en', 'al'):
                value = -0.3
        elif 'h' in before and word == 'at':
            value = 0.3
        if before.endswith('hat') and word == 'i':
            value = 4.5
        if context.lower().endswith(('happ', 'chanc')) and word in ('ens', 'en'):
            value = -5.5
    context = (context + raw)[-200:]
    return (doc, raw, context), value

"""Approximate the first-visible-token pulse, using broad token shapes.

In inspected training rows, large activations concentrate at document
starts. This program is zero elsewhere. At the first token it uses case,
leading space, numeric/punctuation status and script; two letter-piece
categories also get a log-length correction. Individual-token amplitude
differences and small later-token fluctuations are deliberately omitted.
"""
from math import log1p

import regex

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is not None and carry == document:
        return document, 0.0

    text = prefix.token_strings[-1]
    word = text.strip()
    if not word:
        value = 0.0
    elif text.startswith('<|'):
        value = -3.3
    elif word.isnumeric():
        value = -2.3
    elif not any(c.isalnum() for c in word):
        value = -1.7
    elif word.isascii() and word.isalpha():
        spaced = text.startswith(' ')
        if word.isupper():
            value = 4.6 if spaced else -2.8
        elif word.istitle():
            value = 6.4 if spaced else -8.0 + 2.0 * log1p(len(word))
        else:
            value = -1.3 - 1.1 * log1p(len(word)) if spaced else -2.1
    elif word.isascii():
        value = -2.3
    elif regex.search(r'\p{Script=Han}', word):
        value = -3.8
    elif regex.search(r'\p{Script=Cyrillic}|\p{Script=Arabic}', word):
        value = -1.7
    else:
        value = -2.6
    return document, value
